using RealmForge.Domain.Entities;
using RealmForge.Shared.Enums;

namespace RealmForge.Infrastructure.Persistence.Seeding.RulesGlossaryData;

///	<summary>
///	Rules glossary entries (except conditions and actions) of the 2014 rules. English text from the SRD 5.1 (CC BY 4.0); the Italian texts are RealmForge
///	translations that use the official names of the Italian Player's Handbook.
///	</summary>
public static class GlossaryRules2014Seeder
{
	public static IEnumerable<RuleEntry> Build()
	{
		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "cone", RuleCategory.AreaOfEffect,
			related: Array.Empty<string>(),
			en: ("Cone", "A cone extends in a direction you choose from its point of origin. A cone's width at a given point along its length is equal to that point's distance from the point of origin. A cone's area of effect specifies its maximum length.\n\nA cone's point of origin is not included in the cone's area of effect, unless you decide otherwise.",
				new[] { "cone", "cones" }),
			it: ("Cono", "Un cono si estende dal suo punto di origine nella direzione scelta dal creatore. In ogni punto della sua lunghezza, la larghezza del cono è pari alla distanza di quel punto dal punto di origine. L'area di effetto del cono ne specifica la lunghezza massima.\n\nIl punto di origine del cono non è compreso nella sua area di effetto, a meno che il creatore non decida altrimenti.",
				new[] { "cono", "coni" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "cube", RuleCategory.AreaOfEffect,
			related: Array.Empty<string>(),
			en: ("Cube", "You select a cube's point of origin, which lies anywhere on a face of the cubic effect. The cube's size is expressed as the length of each side.\n\nA cube's point of origin is not included in the cube's area of effect, unless you decide otherwise.",
				new[] { "cube", "cubes" }),
			it: ("Cubo", "Il creatore sceglie il punto di origine del cubo, che si trova in un punto qualsiasi di una sua faccia. La dimensione del cubo è espressa dalla lunghezza di ciascun lato.\n\nIl punto di origine del cubo non è compreso nella sua area di effetto, a meno che il creatore non decida altrimenti.",
				new[] { "cubo", "cubi" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "cylinder", RuleCategory.AreaOfEffect,
			related: Array.Empty<string>(),
			en: ("Cylinder", "A cylinder's point of origin is the center of a circle of a particular radius, as given in the spell description. The circle must either be on the ground or at the height of the spell effect. The energy in a cylinder expands in straight lines from the point of origin to the perimeter of the circle, forming the base of the cylinder. The spell's effect then shoots up from the base or down from the top, to a distance equal to the height of the cylinder.\n\nA cylinder's point of origin is included in the cylinder's area of effect.",
				new[] { "cylinder", "cylinders" }),
			it: ("Cilindro", "Il punto di origine di un cilindro è il centro di un cerchio di un determinato raggio, indicato nella descrizione dell'incantesimo. Il cerchio deve trovarsi sul terreno oppure all'altezza dell'effetto dell'incantesimo. L'energia del cilindro si espande in linea retta dal punto di origine fino al perimetro del cerchio, formando la base del cilindro; l'effetto si estende poi verso l'alto dalla base, o verso il basso dalla sommità, per una distanza pari all'altezza del cilindro.\n\nIl punto di origine del cilindro è compreso nella sua area di effetto.",
				new[] { "cilindro", "cilindri" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "line", RuleCategory.AreaOfEffect,
			related: Array.Empty<string>(),
			en: ("Line", "A line extends from its point of origin in a straight path up to its length and covers an area defined by its width.\n\nA line's point of origin is not included in the line's area of effect, unless you decide otherwise.",
				Array.Empty<string>()),
			it: ("Linea", "Una linea si estende in linea retta dal suo punto di origine fino alla sua lunghezza e copre un'area definita dalla sua larghezza.\n\nIl punto di origine della linea non è compreso nella sua area di effetto, a meno che il creatore non decida altrimenti.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "sphere", RuleCategory.AreaOfEffect,
			related: Array.Empty<string>(),
			en: ("Sphere", "You select a sphere's point of origin, and the sphere extends outward from that point. The sphere's size is expressed as a radius in feet that extends from the point.\n\nA sphere's point of origin is included in the sphere's area of effect.",
				new[] { "sphere", "spheres" }),
			it: ("Sfera", "Il creatore sceglie il punto di origine della sfera, che si estende verso l'esterno a partire da quel punto. La dimensione della sfera è espressa dal raggio, in metri, che si estende dal punto di origine.\n\nIl punto di origine della sfera è compreso nella sua area di effetto.",
				new[] { "sfera", "sfere" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "ability-scores-and-modifiers", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Ability Scores and Modifiers", "| Score | Modifier |\n|-------|----------|\n| 1     | -5       |\n| 2-3   | -4       |\n| 4-5   | -3       |\n| 6-7   | -2       |\n| 8-9   | -1       |\n| 10-11 | +0       |\n| 12-13 | +1       |\n| 14-15 | +2       |\n| 16-17 | +3       |\n| 18-19 | +4       |\n| 20-21 | +5       |\n| 22-23 | +6       |\n| 24-25 | +7       |\n| 26-27 | +8       |\n| 28-29 | +9       |\n| 30    | +10      |\n\nTo determine an ability modifier without consulting the table, subtract 10 from the ability score and then divide the total by 2 (round down).\n\nBecause ability modifiers affect almost every attack roll, ability check, and saving throw, ability modifiers come up in play more often than their associated scores.",
				Array.Empty<string>()),
			it: ("Punteggi di caratteristica e modificatori", "| Punteggio | Modificatore |\n|---|---|\n| 1 | −5 |\n| 2–3 | −4 |\n| 4–5 | −3 |\n| 6–7 | −2 |\n| 8–9 | −1 |\n| 10–11 | +0 |\n| 12–13 | +1 |\n| 14–15 | +2 |\n| 16–17 | +3 |\n| 18–19 | +4 |\n| 20–21 | +5 |\n| 22–23 | +6 |\n| 24–25 | +7 |\n| 26–27 | +8 |\n| 28–29 | +9 |\n| 30 | +10 |\n\nPer calcolare un modificatore di caratteristica senza consultare la tabella, si sottrae 10 dal punteggio e si divide il risultato per 2 (arrotondando per difetto).\n\nPoiché i modificatori di caratteristica influiscono su quasi ogni tiro per colpire, prova di caratteristica e tiro salvezza, durante il gioco entrano in campo molto più spesso dei punteggi da cui derivano.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "advantage-and-disadvantage", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Advantage and Disadvantage", "Sometimes a special ability or spell tells you that you have advantage or disadvantage on an ability check, a saving throw, or an attack roll. When that happens, you roll a second d20 when you make the roll. Use the higher of the two rolls if you have advantage, and use the lower roll if you have disadvantage. For example, if you have disadvantage and roll a 17 and a 5, you use the 5. If you instead have advantage and roll those numbers, you use the 17.\n\nIf multiple situations affect a roll and each one grants advantage or imposes disadvantage on it, you don't roll more than one additional d20. If two favorable situations grant advantage, for example, you still roll only one additional d20.\n\nIf circumstances cause a roll to have both advantage and disadvantage, you are considered to have neither of them, and you roll one d20. This is true even if multiple circumstances impose disadvantage and only one grants advantage or vice versa. In such a situation, you have neither advantage nor disadvantage.\n\nWhen you have advantage or disadvantage and something in the game, such as the halfling's Lucky trait, lets you reroll the d20, you can reroll only one of the dice. You choose which one. For example, if a halfling has advantage or disadvantage on an ability check and rolls a 1 and a 13, the halfling could use the Lucky trait to reroll the 1.\n\nYou usually gain advantage or disadvantage through the use of special abilities, actions, or spells. Inspiration can also give a character advantage. The GM can also decide that circumstances influence a roll in one direction or the other and grant advantage or impose disadvantage as a result.",
				new[] { "advantage", "disadvantage" }),
			it: ("Vantaggio e svantaggio", "A volte una capacità speciale o un incantesimo indica che il personaggio dispone di vantaggio o subisce svantaggio a una prova di caratteristica, a un tiro salvezza o a un tiro per colpire. In tal caso, quando effettua il tiro, tira un secondo d20: usa il risultato più alto se dispone di vantaggio, quello più basso se subisce svantaggio. Per esempio, se subisce svantaggio e ottiene 17 e 5, usa il 5; se invece dispone di vantaggio e ottiene gli stessi numeri, usa il 17.\n\nSe più situazioni influenzano un tiro e ciascuna concede vantaggio o impone svantaggio, non si tira più di un d20 aggiuntivo. Se due situazioni favorevoli concedono vantaggio, per esempio, si tira comunque un solo d20 aggiuntivo.\n\nSe le circostanze fanno sì che un tiro abbia sia vantaggio sia svantaggio, si considera che non abbia né l'uno né l'altro e si tira un solo d20. Questo vale anche se più circostanze impongono svantaggio e una sola concede vantaggio, o viceversa.\n\nQuando il personaggio dispone di vantaggio o subisce svantaggio e qualcosa nel gioco, come il tratto Fortunato dell'halfling, gli permette di ripetere il tiro del d20, può ripetere soltanto uno dei due dadi, a sua scelta. Per esempio, se un halfling con vantaggio o svantaggio a una prova di caratteristica ottiene 1 e 13, può usare Fortunato per ripetere l'1.\n\nDi solito si ottiene vantaggio o svantaggio grazie a capacità speciali, azioni o incantesimi; anche l'ispirazione può concedere vantaggio a un personaggio. Il DM può inoltre decidere che le circostanze favoriscano o sfavoriscano un tiro, e concedere vantaggio o imporre svantaggio di conseguenza.",
				new[] { "vantaggio", "svantaggio" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "proficiency-bonus", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Proficiency Bonus", "Characters have a proficiency bonus determined by level. Monsters also have this bonus, which is incorporated in their stat blocks. The bonus is used in the rules on ability checks, saving throws, and attack rolls.\n\nYour proficiency bonus can't be added to a single die roll or other number more than once. For example, if two different rules say you can add your proficiency bonus to a Wisdom saving throw, you nevertheless add the bonus only once when you make the save.\n\nOccasionally, your proficiency bonus might be multiplied or divided (doubled or halved, for example) before you apply it. For example, the rogue's Expertise feature doubles the proficiency bonus for certain ability checks. If a circumstance suggests that your proficiency bonus applies more than once to the same roll, you still add it only once and multiply or divide it only once.\n\nBy the same token, if a feature or effect allows you to multiply your proficiency bonus when making an ability check that wouldn't normally benefit from your proficiency bonus, you still don't add the bonus to the check. For that check your proficiency bonus is 0, given the fact that multiplying 0 by any number is still 0. For instance, if you lack proficiency in the History skill, you gain no benefit from a feature that lets you double your proficiency bonus when you make Intelligence (History) checks.\n\nIn general, you don't multiply your proficiency bonus for attack rolls or saving throws. If a feature or effect allows you to do so, these same rules apply.",
				new[] { "proficiency bonus" }),
			it: ("Bonus di competenza", "I personaggi hanno un bonus di competenza determinato dal livello. Anche i mostri hanno questo bonus, già incluso nelle loro statistiche. Il bonus si usa nelle regole delle prove di caratteristica, dei tiri salvezza e dei tiri per colpire.\n\nIl bonus di competenza non può essere aggiunto più di una volta allo stesso tiro di dado o allo stesso valore. Per esempio, se due regole diverse permettono al personaggio di aggiungere il bonus di competenza a un tiro salvezza su Saggezza, lo aggiunge comunque una sola volta.\n\nTalvolta il bonus di competenza può essere moltiplicato o diviso (per esempio raddoppiato o dimezzato) prima di essere applicato: il privilegio Maestria del ladro, per esempio, raddoppia il bonus di competenza per alcune prove di caratteristica. Se una circostanza suggerisce che il bonus si applichi più di una volta allo stesso tiro, lo si aggiunge comunque una sola volta e lo si moltiplica o divide una sola volta.\n\nAllo stesso modo, se un privilegio o un effetto permette di moltiplicare il bonus di competenza in una prova di caratteristica che normalmente non ne beneficerebbe, il bonus non si aggiunge comunque: per quella prova il bonus di competenza è 0, e 0 moltiplicato per qualsiasi numero resta 0. Per esempio, un personaggio privo di competenza nell'abilità Storia non trae alcun beneficio da un privilegio che gli permette di raddoppiare il bonus di competenza nelle prove di Intelligenza (Storia).\n\nIn generale, il bonus di competenza non si moltiplica per i tiri per colpire o i tiri salvezza; se un privilegio o un effetto lo permette, valgono le stesse regole.",
				new[] { "bonus di competenza" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "ability-check", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Ability Check", "An ability check tests a character's or monster's innate talent and training in an effort to overcome a challenge. The GM calls for an ability check when a character or monster attempts an action (other than an attack) that has a chance of failure. When the outcome is uncertain, the dice determine the results.\n\nFor every ability check, the GM decides which of the six abilities is relevant to the task at hand and the difficulty of the task, represented by a Difficulty Class.\n\nThe more difficult a task, the higher its DC. The Typical Difficulty Classes table shows the most common DCs.\n\n**Typical Difficulty Classes**\n\n| Task Difficulty   | DC |\n|-------------------|----|\n| Very easy         | 5  |\n| Easy              | 10 |\n| Medium            | 15 |\n| Hard              | 20 |\n| Very hard         | 25 |\n| Nearly impossible | 30 |\n\nTo make an ability check, roll a d20 and add the relevant ability modifier. As with other d20 rolls, apply bonuses and penalties, and compare the total to the DC. If the total equals or exceeds the DC, the ability check is a success—the creature overcomes the challenge at hand. Otherwise, it's a failure, which means the character or monster makes no progress toward the objective or makes progress combined with a setback determined by the GM.",
				Array.Empty<string>()),
			it: ("Prove di caratteristica", "Una prova di caratteristica mette alla prova il talento innato e l'addestramento di un personaggio o di un mostro che cerca di superare una sfida. Il DM richiede una prova di caratteristica quando un personaggio o un mostro tenta un'azione (diversa da un attacco) che potrebbe fallire: quando l'esito è incerto, sono i dadi a deciderlo.\n\nPer ogni prova di caratteristica, il DM stabilisce quale delle sei caratteristiche è pertinente e quanto è difficile il compito, rappresentato da una Classe Difficoltà.\n\nPiù un compito è difficile, più alta è la sua CD. La tabella \"Classi Difficoltà tipiche\" riporta le CD più comuni.\n\n**Classi Difficoltà tipiche**\n\n| Difficoltà del compito | CD |\n|---|---|\n| Molto facile | 5 |\n| Facile | 10 |\n| Media | 15 |\n| Difficile | 20 |\n| Molto difficile | 25 |\n| Quasi impossibile | 30 |\n\nPer effettuare una prova di caratteristica si tira un d20 e si aggiunge il modificatore di caratteristica pertinente. Come per gli altri tiri di d20, si applicano bonus e penalità e si confronta il totale con la CD. Se il totale è pari o superiore alla CD, la prova riesce e la creatura supera la sfida; altrimenti fallisce, e il personaggio o il mostro non fa alcun progresso verso l'obiettivo, oppure lo fa ma con un contrattempo stabilito dal DM.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "contests", RuleCategory.Rule,
			related: new[] { "grappling", "shoving-a-creature" },
			en: ("Contests", "Sometimes one character's or monster's efforts are directly opposed to another's. This can occur when both of them are trying to do the same thing and only one can succeed, such as attempting to snatch up a magic ring that has fallen on the floor. This situation also applies when one of them is trying to prevent the other one from accomplishing a goal—for example, when a monster tries to force open a door that an adventurer is holding closed. In situations like these, the outcome is determined by a special form of ability check, called a contest.\n\nBoth participants in a contest make ability checks appropriate to their efforts. They apply all appropriate bonuses and penalties, but instead of comparing the total to a DC, they compare the totals of their two checks. The participant with the higher check total wins the contest. That character or monster either succeeds at the action or prevents the other one from succeeding.\n\nIf the contest results in a tie, the situation remains the same as it was before the contest. Thus, one contestant might win the contest by default. If two characters tie in a contest to snatch a ring off the floor, neither character grabs it. In a contest between a monster trying to open a door and an adventurer trying to keep the door closed, a tie means that the door remains shut.",
				Array.Empty<string>()),
			it: ("Contese", "A volte gli sforzi di un personaggio o di un mostro si oppongono direttamente a quelli di un altro. Succede quando entrambi cercano di fare la stessa cosa e soltanto uno può riuscirci, come afferrare un anello magico caduto sul pavimento, oppure quando uno dei due cerca di impedire all'altro di raggiungere un obiettivo, come quando un mostro cerca di sfondare una porta che un avventuriero tiene chiusa. In situazioni come queste, l'esito si decide con una forma speciale di prova di caratteristica, chiamata contesa.\n\nEntrambi i partecipanti effettuano le prove di caratteristica adatte ai loro sforzi, applicando tutti i bonus e le penalità del caso; invece di confrontare il totale con una CD, però, si confrontano i totali delle due prove. Vince la contesa il partecipante con il totale più alto, che riesce nell'azione o impedisce all'altro di riuscirci.\n\nIn caso di pareggio, la situazione resta invariata, quindi uno dei contendenti può vincere la contesa per default. Se due personaggi pareggiano nel tentativo di afferrare un anello dal pavimento, nessuno dei due lo prende; in una contesa tra un mostro che cerca di aprire una porta e un avventuriero che cerca di tenerla chiusa, il pareggio significa che la porta resta chiusa.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "skills", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Skills", "Each ability covers a broad range of capabilities, including skills that a character or a monster can be proficient in. A skill represents a specific aspect of an ability score, and an individual's proficiency in a skill demonstrates a focus on that aspect. (A character's starting skill proficiencies are determined at character creation, and a monster's skill proficiencies appear in the monster's stat block.)\n\nFor example, a Dexterity check might reflect a character's attempt to pull off an acrobatic stunt, to palm an object, or to stay hidden. Each of these aspects of Dexterity has an associated skill: Acrobatics, Sleight of Hand, and Stealth, respectively. So a character who has proficiency in the Stealth skill is particularly good at Dexterity checks related to sneaking and hiding.\n\nThe skills related to each ability score are shown in the following table. (No skills are related to Constitution.)\n\n| Ability | Skills |\n|---|---|\n| Strength | Athletics |\n| Dexterity | Acrobatics, Sleight of Hand, Stealth |\n| Intelligence | Arcana, History, Investigation, Nature, Religion |\n| Wisdom | Animal Handling, Insight, Medicine, Perception, Survival |\n| Charisma | Deception, Intimidation, Performance, Persuasion |\n\nSometimes, the GM might ask for an ability check using a specific skill—for example, \"Make a Wisdom (Perception) check.\" At other times, a player might ask the GM if proficiency in a particular skill applies to a check. In either case, proficiency in a skill means an individual can add his or her proficiency bonus to ability checks that involve that skill. Without proficiency in the skill, the individual makes a normal ability check.\n\nFor example, if a character attempts to climb up a dangerous cliff, the GM might ask for a Strength (Athletics) check. If the character is proficient in Athletics, the character's proficiency bonus is added to the Strength check. If the character lacks that proficiency, he or she just makes a Strength check.",
				Array.Empty<string>()),
			it: ("Abilità", "Ogni caratteristica comprende un ampio ventaglio di capacità, tra cui le abilità in cui un personaggio o un mostro può avere competenza. Un'abilità rappresenta un aspetto specifico di un punteggio di caratteristica, e la competenza in un'abilità indica che chi la possiede si è specializzato in quell'aspetto. (Le competenze nelle abilità iniziali di un personaggio si stabiliscono durante la sua creazione, mentre quelle di un mostro compaiono nelle sue statistiche.)\n\nPer esempio, una prova di Destrezza potrebbe rappresentare il tentativo di eseguire un'acrobazia, di far sparire un oggetto con destrezza o di restare nascosti. Ognuno di questi aspetti della Destrezza ha un'abilità associata: rispettivamente Acrobazia, Rapidità di Mano e Furtività. Un personaggio con competenza nell'abilità Furtività è quindi particolarmente bravo nelle prove di Destrezza legate al muoversi di soppiatto e al nascondersi.\n\nLe abilità associate a ciascun punteggio di caratteristica sono indicate nella tabella seguente. (Nessuna abilità è associata alla Costituzione.)\n\n| Caratteristica | Abilità |\n|---|---|\n| Forza | Atletica |\n| Destrezza | Acrobazia, Rapidità di Mano, Furtività |\n| Intelligenza | Arcano, Storia, Indagare, Natura, Religione |\n| Saggezza | Addestrare Animali, Intuizione, Medicina, Percezione, Sopravvivenza |\n| Carisma | Inganno, Intimidire, Intrattenere, Persuasione |\n\nA volte il DM può chiedere una prova di caratteristica legata a un'abilità specifica, per esempio: \"Effettua una prova di Saggezza (Percezione)\". Altre volte è un giocatore a chiedere al DM se la competenza in una certa abilità si applica a una prova. In entrambi i casi, avere competenza in un'abilità significa poter aggiungere il proprio bonus di competenza alle prove di caratteristica che la riguardano; senza quella competenza, si effettua una normale prova di caratteristica.\n\nPer esempio, se un personaggio cerca di arrampicarsi su una scogliera pericolosa, il DM potrebbe chiedere una prova di Forza (Atletica). Se il personaggio ha competenza in Atletica, aggiunge il suo bonus di competenza alla prova di Forza; altrimenti effettua soltanto una prova di Forza.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "passive-checks", RuleCategory.Rule,
			related: new[] { "surprise" },
			en: ("Passive Checks", "A passive check is a special kind of ability check that doesn't involve any die rolls. Such a check can represent the average result for a task done repeatedly, such as searching for secret doors over and over again, or can be used when the GM wants to secretly determine whether the characters succeed at something without rolling dice, such as noticing a hidden monster.\n\nHere's how to determine a character's total for a passive check:\n\n10 + all modifiers that normally apply to the check\n\nIf the character has advantage on the check, add 5. For disadvantage, subtract 5. The game refers to a passive check total as a **score**.\n\nFor example, if a 1st-level character has a Wisdom of 15 and proficiency in Perception, he or she has a passive Wisdom (Perception) score of 14.",
				new[] { "passive check", "passive checks", "passive Perception" }),
			it: ("Prove passive", "Una prova passiva è un tipo speciale di prova di caratteristica che non prevede tiri di dado. Può rappresentare il risultato medio di un compito svolto ripetutamente, come cercare più e più volte una porta segreta, oppure può essere usata quando il DM vuole stabilire in segreto se i personaggi riescono in qualcosa senza tirare i dadi, come notare un mostro nascosto.\n\nEcco come si calcola il totale di una prova passiva per un personaggio:\n\n10 + tutti i modificatori che normalmente si applicano alla prova\n\nSe il personaggio dispone di vantaggio alla prova, si aggiunge 5; se subisce svantaggio, si sottrae 5. Il gioco chiama **punteggio** il totale di una prova passiva.\n\nPer esempio, un personaggio di 1° livello con Saggezza 15 e competenza in Percezione ha un punteggio passivo di Saggezza (Percezione) pari a 14.",
				new[] { "prova passiva", "prove passive", "percezione passiva" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "working-together", RuleCategory.Rule,
			related: new[] { "help" },
			en: ("Working Together", "Sometimes two or more characters team up to attempt a task. The character who's leading the effort—or the one with the highest ability modifier-can make an ability check with advantage, reflecting the help provided by the other characters. In combat, this requires the Help action.\n\nA character can only provide help if the task is one that he or she could attempt alone. For example, trying to open a lock requires proficiency with thieves' tools, so a character who lacks that proficiency can't help another character in that task. Moreover, a character can help only when two or more individuals working together would actually be productive. Some tasks, such as threading a needle, are no easier with help.\n\n**Group Checks**\n\nWhen a number of individuals are trying to accomplish something as a group, the GM might ask for a group ability check. In such a situation, the characters who are skilled at a particular task help cover those who aren't.\n\nTo make a group ability check, everyone in the group makes the ability check. If at least half the group succeeds, the whole group succeeds. Otherwise, the group fails.\n\nGroup checks don't come up very often, and they're most useful when all the characters succeed or fail as a group. For example, when adventurers are navigating a swamp, the GM might call for a group Wisdom (Survival) check to see if the characters can avoid the quicksand, sinkholes, and other natural hazards of the environment. If at least half the group succeeds, the successful characters are able to guide their companions out of danger. Otherwise, the group stumbles into one of these hazards.",
				Array.Empty<string>()),
			it: ("Collaborare", "A volte due o più personaggi si uniscono per tentare un compito. Il personaggio che guida l'impresa, o quello con il modificatore di caratteristica più alto, può effettuare una prova di caratteristica con vantaggio, che rappresenta l'aiuto fornito dagli altri. In combattimento, questo richiede l'azione di Aiuto.\n\nUn personaggio può aiutare solo in un compito che potrebbe tentare da solo. Per esempio, aprire una serratura richiede la competenza negli arnesi da scasso, quindi un personaggio privo di quella competenza non può aiutarne un altro in quel compito. Inoltre, si può aiutare solo quando il lavoro di due o più persone insieme è davvero utile: alcuni compiti, come infilare un ago, non diventano più facili con l'aiuto di qualcuno.\n\n**Prove di gruppo**\n\nQuando più persone cercano di ottenere qualcosa come gruppo, il DM può chiedere una prova di caratteristica di gruppo. In questa situazione, i personaggi esperti in un certo compito compensano quelli che non lo sono.\n\nPer effettuare una prova di gruppo, tutti i membri del gruppo effettuano la prova di caratteristica. Se almeno metà del gruppo riesce, riesce l'intero gruppo; altrimenti il gruppo fallisce.\n\nLe prove di gruppo non capitano spesso e sono utili soprattutto quando tutti i personaggi riescono o falliscono insieme. Per esempio, quando gli avventurieri attraversano una palude, il DM potrebbe chiedere una prova di gruppo di Saggezza (Sopravvivenza) per vedere se i personaggi evitano sabbie mobili, voragini e altri pericoli naturali. Se almeno metà del gruppo riesce, i personaggi che hanno avuto successo guidano i compagni fuori pericolo; altrimenti il gruppo finisce in uno di quei pericoli.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "saving-throws", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Saving Throws", "A saving throw-also called a save—represents an attempt to resist a spell, a trap, a poison, a disease, or a similar threat. You don't normally decide to make a saving throw; you are forced to make one because your character or monster is at risk of harm.\n\nTo make a saving throw, roll a d20 and add the appropriate ability modifier. For example, you use your Dexterity modifier for a Dexterity saving throw.\n\nA saving throw can be modified by a situational bonus or penalty and can be affected by advantage and disadvantage, as determined by the GM.\n\nEach class gives proficiency in at least two saving throws. The wizard, for example, is proficient in Intelligence saves. As with skill proficiencies, proficiency in a saving throw lets a character add his or her proficiency bonus to saving throws made using a particular ability score. Some monsters have saving throw proficiencies as well.\n\nThe Difficulty Class for a saving throw is determined by the effect that causes it. For example, the DC for a saving throw allowed by a spell is determined by the caster's spellcasting ability and proficiency bonus.\n\nThe result of a successful or failed saving throw is also detailed in the effect that allows the save. Usually, a successful save means that a creature suffers no harm, or reduced harm, from an effect.",
				Array.Empty<string>()),
			it: ("Tiri salvezza", "Un tiro salvezza rappresenta il tentativo di resistere a un incantesimo, una trappola, un veleno, una malattia o una minaccia simile. Di solito non si decide di effettuare un tiro salvezza: si è costretti a farlo perché il personaggio o il mostro rischia di subire un danno.\n\nPer effettuare un tiro salvezza si tira un d20 e si aggiunge il modificatore di caratteristica appropriato: per un tiro salvezza su Destrezza, per esempio, si usa il modificatore di Destrezza.\n\nUn tiro salvezza può essere modificato da un bonus o da una penalità dovuti alla situazione e può essere influenzato da vantaggio e svantaggio, secondo quanto stabilito dal DM.\n\nOgni classe concede la competenza in almeno due tiri salvezza: il mago, per esempio, ha competenza nei tiri salvezza su Intelligenza. Come per le abilità, la competenza in un tiro salvezza permette a un personaggio di aggiungere il suo bonus di competenza ai tiri salvezza basati su quel punteggio di caratteristica. Anche alcuni mostri hanno competenze nei tiri salvezza.\n\nLa Classe Difficoltà di un tiro salvezza è determinata dall'effetto che lo richiede: per esempio, la CD del tiro salvezza contro un incantesimo dipende dalla caratteristica da incantatore e dal bonus di competenza di chi lo lancia.\n\nAnche il risultato di un tiro salvezza superato o fallito è descritto nell'effetto che lo richiede. Di solito, superarlo significa che la creatura non subisce danni da quell'effetto, o ne subisce di meno.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "surprise", RuleCategory.Rule,
			related: new[] { "passive-checks", "initiative" },
			en: ("Surprise", "A band of adventurers sneaks up on a bandit camp, springing from the trees to attack them. A gelatinous cube glides down a dungeon passage, unnoticed by the adventurers until the cube engulfs one of them. In these situations, one side of the battle gains surprise over the other.\n\nThe GM determines who might be surprised. If neither side tries to be stealthy, they automatically notice each other. Otherwise, the GM compares the Dexterity (Stealth) checks of anyone hiding with the passive Wisdom (Perception) score of each creature on the opposing side. Any character or monster that doesn't notice a threat is surprised at the start of the encounter.\n\nIf you're surprised, you can't move or take an action on your first turn of the combat, and you can't take a reaction until that turn ends. A member of a group can be surprised even if the other members aren't.",
				new[] { "surprised" }),
			it: ("Sorpresa", "Un gruppo di avventurieri si avvicina di soppiatto a un accampamento di banditi e balza fuori dagli alberi per attaccarli; un cubo gelatinoso scivola lungo un corridoio del dungeon, inosservato finché non inghiotte uno degli avventurieri. In situazioni come queste, una delle due parti coglie l'altra di sorpresa.\n\nÈ il DM a stabilire chi potrebbe essere sorpreso. Se nessuna delle due parti cerca di essere furtiva, si notano a vicenda automaticamente; altrimenti il DM confronta le prove di Destrezza (Furtività) di chi si nasconde con il punteggio passivo di Saggezza (Percezione) di ogni creatura della parte avversaria. Qualsiasi personaggio o mostro che non nota una minaccia è sorpreso all'inizio dell'incontro.\n\nUn personaggio sorpreso non può muoversi né effettuare azioni nel suo primo turno di combattimento, e non può effettuare reazioni finché quel turno non termina. Un membro di un gruppo può essere sorpreso anche se gli altri non lo sono.",
				new[] { "sorpreso", "sorpresa", "sorpresi", "sorprese" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "initiative", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Initiative", "Initiative determines the order of turns during combat. When combat starts, every participant makes a Dexterity check to determine their place in the initiative order. The GM makes one roll for an entire group of identical creatures, so each member of the group acts at the same time.\n\nThe GM ranks the combatants in order from the one with the highest Dexterity check total to the one with the lowest. This is the order (called the initiative order) in which they act during each round. The initiative order remains the same from round to round.\n\nIf a tie occurs, the GM decides the order among tied GM-controlled creatures, and the players decide the order among their tied characters. The GM can decide the order if the tie is between a monster and a player character. Optionally, the GM can have the tied characters and monsters each roll a d20 to determine the order, highest roll going first.",
				new[] { "initiative" }),
			it: ("Iniziativa", "L'iniziativa determina l'ordine dei turni durante il combattimento. Quando il combattimento inizia, ogni partecipante effettua una prova di Destrezza per stabilire il proprio posto nell'ordine di iniziativa. Il DM effettua un solo tiro per un intero gruppo di creature identiche, che agiscono quindi tutte nello stesso momento.\n\nIl DM ordina i combattenti dal totale della prova di Destrezza più alto al più basso: è l'ordine (detto ordine di iniziativa) in cui agiscono in ogni round, e resta lo stesso da un round all'altro.\n\nIn caso di pareggio, il DM decide l'ordine tra le creature che controlla, mentre i giocatori decidono l'ordine tra i loro personaggi; se il pareggio è tra un mostro e un personaggio giocante, decide il DM. In alternativa, il DM può far tirare un d20 ai personaggi e ai mostri in parità: il risultato più alto agisce per primo.",
				new[] { "iniziativa" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "bonus-actions", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Bonus Actions", "Various class features, spells, and other abilities let you take an additional action on your turn called a bonus action. The Cunning Action feature, for example, allows a rogue to take a bonus action. You can take a bonus action only when a special ability, spell, or other feature of the game states that you can do something as a bonus action. You otherwise don't have a bonus action to take.\n\nYou can take only one bonus action on your turn, so you must choose which bonus action to use when you have more than one available.\n\nYou choose when to take a bonus action during your turn, unless the bonus action's timing is specified, and anything that deprives you of your ability to take actions also prevents you from taking a bonus action.",
				new[] { "bonus action", "bonus actions" }),
			it: ("Azioni bonus", "Vari privilegi di classe, incantesimi e altre capacità permettono di effettuare nel proprio turno un'azione aggiuntiva chiamata azione bonus. Il privilegio Azione Scaltra, per esempio, permette a un ladro di effettuare un'azione bonus. Si può effettuare un'azione bonus solo quando una capacità speciale, un incantesimo o un altro elemento del gioco dice che si può fare qualcosa come azione bonus; altrimenti non si dispone di alcuna azione bonus.\n\nSi può effettuare una sola azione bonus per turno, quindi quando ne sono disponibili più di una bisogna scegliere quale usare.\n\nIl personaggio sceglie quando effettuare l'azione bonus durante il suo turno, a meno che non sia specificato un momento preciso; qualsiasi cosa gli impedisca di effettuare azioni gli impedisce anche di effettuare azioni bonus.",
				new[] { "azione bonus", "azioni bonus" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "reactions", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Reactions", "Certain special abilities, spells, and situations allow you to take a special action called a reaction. A reaction is an instant response to a trigger of some kind, which can occur on your turn or on someone else's. The opportunity attack is the most common type of reaction.\n\nWhen you take a reaction, you can't take another one until the start of your next turn. If the reaction interrupts another creature's turn, that creature can continue its turn right after the reaction.",
				new[] { "reaction", "reactions" }),
			it: ("Reazioni", "Alcune capacità speciali, incantesimi e situazioni permettono di effettuare un'azione speciale chiamata reazione. Una reazione è una risposta immediata a un evento scatenante, che può verificarsi nel turno del personaggio o in quello di qualcun altro. L'attacco di opportunità è il tipo di reazione più comune.\n\nDopo aver effettuato una reazione, il personaggio non può effettuarne un'altra fino all'inizio del suo turno successivo. Se la reazione interrompe il turno di un'altra creatura, quella creatura può proseguire il suo turno subito dopo la reazione.",
				new[] { "reazione", "reazioni" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "difficult-terrain", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Difficult Terrain", "Combat rarely takes place in bare rooms or on featureless plains. Boulder-strewn caverns, briar-choked forests, treacherous staircases—the setting of a typical fight contains difficult terrain.\n\nEvery foot of movement in difficult terrain costs 1 extra foot. This rule is true even if multiple things in a space count as difficult terrain.\n\nLow furniture, rubble, undergrowth, steep stairs, snow, and shallow bogs are examples of difficult terrain. The space of another creature, whether hostile or not, also counts as difficult terrain.",
				new[] { "difficult terrain" }),
			it: ("Terreno difficile", "Il combattimento si svolge di rado in stanze spoglie o su pianure prive di ostacoli: caverne disseminate di massi, foreste soffocate dai rovi, scalinate insidiose... lo scenario di uno scontro tipico contiene terreno difficile.\n\nOgni metro di movimento su terreno difficile costa 1 metro in più. Questa regola vale anche se in uno stesso spazio sono presenti più elementi che contano come terreno difficile.\n\nMobili bassi, macerie, sottobosco, scale ripide, neve e acquitrini poco profondi sono esempi di terreno difficile. Anche lo spazio di un'altra creatura, ostile o meno, conta come terreno difficile.",
				new[] { "terreno difficile" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "being-prone", RuleCategory.Rule,
			related: new[] { "prone" },
			en: ("Being Prone", "Combatants often find themselves lying on the ground, either because they are knocked down or because they throw themselves down. In the game, they are prone.\n\nYou can **drop prone** without using any of your speed. **Standing up** takes more effort; doing so costs an amount of movement equal to half your speed. For example, if your speed is 30 feet, you must spend 15 feet of movement to stand up. You can't stand up if you don't have enough movement left or if your speed is 0.\n\nTo move while prone, you must **crawl** or use magic such as teleportation. Every foot of movement while crawling costs 1 extra foot. Crawling 1 foot in difficult terrain, therefore, costs 3 feet of movement.",
				Array.Empty<string>()),
			it: ("Creature prone", "I combattenti si ritrovano spesso a terra, perché vengono atterrati o perché si gettano al suolo. In termini di gioco sono proni, una condizione descritta nel glossario.\n\nIl personaggio può **gettarsi a terra** senza spendere velocità. **Rialzarsi** richiede uno sforzo maggiore e costa una quantità di movimento pari a metà della sua velocità: per esempio, se la sua velocità è di 9 metri, deve spendere 4,5 metri di movimento per rialzarsi. Non può rialzarsi se non gli resta abbastanza movimento o se la sua velocità è 0.\n\nPer muoversi mentre è prono, deve **strisciare** o usare la magia, come il teletrasporto. Strisciando, ogni metro di movimento costa 1 metro in più: strisciare per 1 metro su terreno difficile, quindi, costa 3 metri di movimento.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "moving-around-other-creatures", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Moving Around Other Creatures", "You can move through a nonhostile creature's space. In contrast, you can move through a hostile creature's space only if the creature is at least two sizes larger or smaller than you. Remember that another creature's space is difficult terrain for you.\n\nWhether a creature is a friend or an enemy, you can't willingly end your move in its space.\n\nIf you leave a hostile creature's reach during your move, you provoke an opportunity attack.",
				Array.Empty<string>()),
			it: ("Muoversi attorno ad altre creature", "Il personaggio può attraversare lo spazio di una creatura non ostile. Può invece attraversare lo spazio di una creatura ostile solo se quella creatura è di almeno due taglie più grande o più piccola di lui. Va ricordato che lo spazio di un'altra creatura è terreno difficile.\n\nChe una creatura sia amica o nemica, il personaggio non può terminare volontariamente il suo movimento nel suo spazio.\n\nSe durante il suo movimento esce dalla portata di una creatura ostile, provoca un attacco di opportunità.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "flying-movement", RuleCategory.Rule,
			related: new[] { "prone" },
			en: ("Flying Movement", "Flying creatures enjoy many benefits of mobility, but they must also deal with the danger of falling. If a flying creature is knocked prone, has its speed reduced to 0, or is otherwise deprived of the ability to move, the creature falls, unless it has the ability to hover or it is being held aloft by magic, such as by the _fly_ spell.",
				Array.Empty<string>()),
			it: ("Movimento in volo", "Le creature volanti godono di grande mobilità, ma devono anche fare i conti con il pericolo di cadere. Se una creatura volante viene resa prona, se la sua velocità scende a 0 o se perde in qualche altro modo la capacità di muoversi, cade, a meno che non sia in grado di fluttuare o non sia tenuta in aria dalla magia, come l'incantesimo _Volare_.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "creature-size", RuleCategory.Rule,
			related: new[] { "squeezing-into-a-smaller-space", "moving-around-other-creatures" },
			en: ("Creature Size", "Each creature takes up a different amount of space. The Size Categories table shows how much space a creature of a particular size controls in combat. Objects sometimes use the same size categories.\n\n**Size Categories**\n\n| Size       | Space                  |\n|------------|------------------------|\n| Tiny       | 2½ by 2½ ft.|\n| Small      | 5 by 5 ft.             |\n| Medium     | 5 by 5 ft.             |\n| Large      | 10 by 10 ft.           |\n| Huge       | 15 by 15 ft.           |\n| Gargantuan | 20 by 20 ft. or larger |\n\n**Space**\n\nA creature's space is the area in feet that it effectively controls in combat, not an expression of its physical dimensions. A typical Medium creature isn't 5 feet wide, for example, but it does control a space that wide. If a Medium hobgoblin stands in a 5-foot-wide doorway, other creatures can't get through unless the hobgoblin lets them.\n\nA creature's space also reflects the area it needs to fight effectively. For that reason, there's a limit to the number of creatures that can surround another creature in combat. Assuming Medium combatants, eight creatures can fit in a 5-foot radius around another one.\n\nBecause larger creatures take up more space, fewer of them can surround a creature. If five Large creatures crowd around a Medium or smaller one, there's little room for anyone else. In contrast, as many as twenty Medium creatures can surround a Gargantuan one.",
				Array.Empty<string>()),
			it: ("Taglia delle creature", "Ogni creatura occupa uno spazio diverso. La tabella \"Categorie di taglia\" indica quanto spazio controlla in combattimento una creatura di una certa taglia. A volte anche gli oggetti usano le stesse categorie di taglia.\n\n**Categorie di taglia**\n\n| Taglia | Spazio |\n|---|---|\n| Minuscola | 0,75 × 0,75 m |\n| Piccola | 1,5 × 1,5 m |\n| Media | 1,5 × 1,5 m |\n| Grande | 3 × 3 m |\n| Enorme | 4,5 × 4,5 m |\n| Mastodontica | 6 × 6 m o più |\n\n**Spazio**\n\nLo spazio di una creatura è l'area che controlla effettivamente in combattimento, non una misura delle sue dimensioni fisiche. Una tipica creatura Media non è larga 1,5 metri, ma controlla uno spazio di quella larghezza: se un hobgoblin Medio si piazza in un vano largo 1,5 metri, le altre creature non possono passare a meno che non sia lui a lasciarle passare.\n\nLo spazio di una creatura riflette anche l'area di cui ha bisogno per combattere efficacemente. Per questo c'è un limite al numero di creature che possono circondarne un'altra in combattimento: considerando combattenti Medi, otto creature possono stare in un raggio di 1,5 metri attorno a un'altra.\n\nDato che le creature più grandi occupano più spazio, ne servono di meno per circondare una creatura. Se cinque creature Grandi si affollano attorno a una creatura Media o più piccola, resta poco spazio per chiunque altro; al contrario, fino a venti creature Medie possono circondarne una Mastodontica.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "squeezing-into-a-smaller-space", RuleCategory.Rule,
			related: new[] { "creature-size" },
			en: ("Squeezing into a Smaller Space", "A creature can squeeze through a space that is large enough for a creature one size smaller than it. Thus, a Large creature can squeeze through a passage that's only 5 feet wide. While squeezing through a space, a creature must spend 1 extra foot for every foot it moves there, and it has disadvantage on attack rolls and Dexterity saving throws. Attack rolls against the creature have advantage while it's in the smaller space.",
				Array.Empty<string>()),
			it: ("Stringersi in uno spazio più piccolo", "Una creatura può passare stringendosi in uno spazio abbastanza ampio per una creatura di una taglia inferiore alla sua: una creatura Grande, per esempio, può passare in un corridoio largo solo 1,5 metri. Mentre si stringe in uno spazio, la creatura deve spendere 1 metro in più per ogni metro di movimento e subisce svantaggio ai tiri per colpire e ai tiri salvezza su Destrezza; i tiri per colpire contro di lei dispongono di vantaggio finché si trova nello spazio più piccolo.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "attack-rolls", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Attack Rolls", "When you make an attack, your attack roll determines whether the attack hits or misses. To make an attack roll, roll a d20 and add the appropriate modifiers. If the total of the roll plus modifiers equals or exceeds the target's Armor Class (AC), the attack hits. The AC of a character is determined at character creation, whereas the AC of a monster is in its stat block.\n\n**Modifiers to the Roll**\n\nWhen a character makes an attack roll, the two most common modifiers to the roll are an ability modifier and the character's proficiency bonus. When a monster makes an attack roll, it uses whatever modifier is provided in its stat block.\n\n**Ability Modifier.** The ability modifier used for a melee weapon attack is Strength, and the ability modifier used for a ranged weapon attack is Dexterity. Weapons that have the finesse or thrown property break this rule.\n\nSome spells also require an attack roll. The ability modifier used for a spell attack depends on the spellcasting ability of the spellcaster.\n\n**Proficiency Bonus.** You add your proficiency bonus to your attack roll when you attack using a weapon with which you have proficiency, as well as when you attack with a spell.\n\n**Rolling 1 or 20**\n\nSometimes fate blesses or curses a combatant, causing the novice to hit and the veteran to miss.\n\nIf the d20 roll for an attack is a 20, the attack hits regardless of any modifiers or the target's AC. This is called a critical hit.\n\nIf the d20 roll for an attack is a 1, the attack misses regardless of any modifiers or the target's AC.",
				Array.Empty<string>()),
			it: ("Tiri per colpire", "Quando il personaggio effettua un attacco, il tiro per colpire stabilisce se l'attacco va a segno. Per effettuare un tiro per colpire si tira un d20 e si aggiungono i modificatori appropriati: se il totale è pari o superiore alla Classe Armatura (CA) del bersaglio, l'attacco colpisce. La CA di un personaggio si stabilisce durante la sua creazione, mentre quella di un mostro compare nelle sue statistiche.\n\n**Modificatori al tiro**\n\nQuando un personaggio effettua un tiro per colpire, i due modificatori più comuni sono un modificatore di caratteristica e il bonus di competenza. Un mostro usa il modificatore indicato nelle sue statistiche.\n\n**Modificatore di caratteristica.** Negli attacchi con armi da mischia si usa il modificatore di Forza, in quelli con armi a distanza il modificatore di Destrezza. Le armi con la proprietà accurata o da lancio fanno eccezione a questa regola.\n\nAnche alcuni incantesimi richiedono un tiro per colpire: il modificatore di caratteristica usato per un attacco con incantesimo dipende dalla caratteristica da incantatore di chi lo lancia.\n\n**Bonus di competenza.** Il personaggio aggiunge il suo bonus di competenza al tiro per colpire quando attacca con un'arma in cui ha competenza, e quando attacca con un incantesimo.\n\n**Ottenere 1 o 20**\n\nA volte il destino benedice o maledice un combattente, permettendo al novellino di colpire e facendo mancare il bersaglio al veterano.\n\nSe il d20 di un attacco dà 20, l'attacco colpisce a prescindere da qualsiasi modificatore e dalla CA del bersaglio: si tratta di un colpo critico.\n\nSe il d20 di un attacco dà 1, l'attacco manca a prescindere da qualsiasi modificatore e dalla CA del bersaglio.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "unseen-attackers-and-targets", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Unseen Attackers and Targets", "Combatants often try to escape their foes' notice by hiding, casting the invisibility spell, or lurking in darkness.\n\nWhen you attack a target that you can't see, you have disadvantage on the attack roll. This is true whether you're guessing the target's location or you're targeting a creature you can hear but not see. If the target isn't in the location you targeted, you automatically miss, but the GM typically just says that the attack missed, not whether you guessed the target's location correctly.\n\nWhen a creature can't see you, you have advantage on attack rolls against it. If you are hidden—both unseen and unheard-when you make an attack, you give away your location when the attack hits or misses.",
				Array.Empty<string>()),
			it: ("Attaccanti e bersagli non visibili", "I combattenti cercano spesso di sfuggire all'attenzione dei nemici nascondendosi, lanciando l'incantesimo _Invisibilità_ o restando nell'oscurità.\n\nQuando il personaggio attacca un bersaglio che non può vedere, subisce svantaggio al tiro per colpire, sia che stia tirando a indovinare la posizione del bersaglio, sia che stia prendendo di mira una creatura che può sentire ma non vedere. Se il bersaglio non si trova nel punto attaccato, l'attacco manca automaticamente; di solito, però, il DM dice soltanto che l'attacco è andato a vuoto, senza rivelare se la posizione era giusta.\n\nQuando una creatura non può vedere il personaggio, lui dispone di vantaggio ai tiri per colpire contro di lei. Se è nascosto (né visto né sentito) quando attacca, rivela la sua posizione, che l'attacco vada a segno o meno.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "ranged-attacks", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Ranged Attacks", "When you make a ranged attack, you fire a bow or a crossbow, hurl a handaxe, or otherwise send projectiles to strike a foe at a distance. A monster might shoot spines from its tail. Many spells also involve making a ranged attack.\n\n**Range**\n\nYou can make ranged attacks only against targets within a specified range.\n\nIf a ranged attack, such as one made with a spell, has a single range, you can't attack a target beyond this range.\n\nSome ranged attacks, such as those made with a longbow or a shortbow, have two ranges. The smaller number is the normal range, and the larger number is the long range. Your attack roll has disadvantage when your target is beyond normal range, and you can't attack a target beyond the long range.\n\n**Ranged Attacks in Close Combat**\n\nAiming a ranged attack is more difficult when a foe is next to you. When you make a ranged attack with a weapon, a spell, or some other means, you have disadvantage on the attack roll if you are within 5 feet of a hostile creature who can see you and who isn't incapacitated.",
				Array.Empty<string>()),
			it: ("Attacchi a distanza", "Effettuare un attacco a distanza significa tirare con un arco o una balestra, scagliare un'ascia o lanciare in qualche altro modo dei proiettili contro un nemico lontano. Un mostro potrebbe scagliare gli aculei della sua coda, e anche molti incantesimi prevedono un attacco a distanza.\n\n**Gittata**\n\nGli attacchi a distanza si possono effettuare solo contro bersagli entro una certa gittata.\n\nSe un attacco a distanza, come quello di un incantesimo, ha una sola gittata, non si può attaccare un bersaglio oltre quella distanza.\n\nAlcuni attacchi a distanza, come quelli con l'arco lungo o l'arco corto, hanno due gittate: il numero più piccolo è la gittata normale, quello più grande la gittata lunga. Il tiro per colpire subisce svantaggio se il bersaglio si trova oltre la gittata normale, e non si può attaccare un bersaglio oltre la gittata lunga.\n\n**Attacchi a distanza in combattimento ravvicinato**\n\nMirare con un attacco a distanza è più difficile quando un nemico è vicino. Quando effettua un attacco a distanza con un'arma, un incantesimo o in altro modo, il personaggio subisce svantaggio al tiro per colpire se si trova entro 1,5 metri da una creatura ostile che può vederlo e che non è incapacitata.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "opportunity-attacks", RuleCategory.Rule,
			related: new[] { "disengage", "reactions" },
			en: ("Opportunity Attacks", "In a fight, everyone is constantly watching for a chance to strike an enemy who is fleeing or passing by. Such a strike is called an opportunity attack.\n\nYou can make an opportunity attack when a hostile creature that you can see moves out of your reach. To make the opportunity attack, you use your reaction to make one melee attack against the provoking creature. The attack occurs right before the creature leaves your reach.\n\nYou can avoid provoking an opportunity attack by taking the Disengage action. You also don't provoke an opportunity attack when you teleport or when someone or something moves you without using your movement, action, or reaction. For example, you don't provoke an opportunity attack if an explosion hurls you out of a foe's reach or if gravity causes you to fall past an enemy.",
				new[] { "opportunity attack", "opportunity attacks" }),
			it: ("Attacchi di opportunità", "In uno scontro, tutti stanno costantemente all'erta, pronti a colpire un nemico che fugge o che passa vicino. Un colpo di questo tipo si chiama attacco di opportunità.\n\nIl personaggio può effettuare un attacco di opportunità quando una creatura ostile che può vedere esce dalla sua portata. Per farlo usa la sua reazione ed effettua un attacco in mischia contro la creatura che lo ha provocato. L'attacco avviene appena prima che la creatura esca dalla sua portata.\n\nSi può evitare di provocare un attacco di opportunità effettuando l'azione di Disimpegno. Non si provoca un attacco di opportunità nemmeno quando ci si teletrasporta o quando qualcuno o qualcosa sposta il personaggio senza che lui usi il suo movimento, la sua azione o la sua reazione: per esempio, non si provoca un attacco di opportunità se un'esplosione scaraventa il personaggio fuori dalla portata di un nemico o se cadendo gli passa accanto.",
				new[] { "attacco di opportunità", "attacchi di opportunità" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "two-weapon-fighting", RuleCategory.Rule,
			related: new[] { "attack", "bonus-actions" },
			en: ("Two-Weapon Fighting", "When you take the Attack action and attack with a light melee weapon that you're holding in one hand, you can use a bonus action to attack with a different light melee weapon that you're holding in the other hand. You don't add your ability modifier to the damage of the bonus attack, unless that modifier is negative.\n\nIf either weapon has the thrown property, you can throw the weapon, instead of making a melee attack with it.",
				new[] { "two-weapon fighting" }),
			it: ("Combattere con due armi", "Quando effettua l'azione di Attacco e attacca con un'arma da mischia leggera impugnata in una mano, il personaggio può usare un'azione bonus per attaccare con un'altra arma da mischia leggera impugnata nell'altra mano. Ai danni dell'attacco bonus non si aggiunge il modificatore di caratteristica, a meno che non sia negativo.\n\nSe una delle due armi ha la proprietà da lancio, il personaggio può lanciarla invece di usarla per un attacco in mischia.",
				new[] { "combattere con due armi" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "grappling", RuleCategory.Rule,
			related: new[] { "grappled", "shoving-a-creature" },
			en: ("Grappling", "When you want to grab a creature or wrestle with it, you can use the Attack action to make a special melee attack, a grapple. If you're able to make multiple attacks with the Attack action, this attack replaces one of them.\n\nThe target of your grapple must be no more than one size larger than you and must be within your reach. Using at least one free hand, you try to seize the target by making a grapple check instead of an attack roll: a Strength (Athletics) check contested by the target's Strength (Athletics) or Dexterity (Acrobatics) check (the target chooses the ability to use). If you succeed, you subject the target to the grappled condition. The condition specifies the things that end it, and you can release the target whenever you like (no action required).\n\n**Escaping a Grapple.** A grappled creature can use its action to escape. To do so, it must succeed on a Strength (Athletics) or Dexterity (Acrobatics) check contested by your Strength (Athletics) check.\n\n**Moving a Grappled Creature.** When you move, you can drag or carry the grappled creature with you, but your speed is halved, unless the creature is two or more sizes smaller than you.",
				new[] { "grapple" }),
			it: ("Lottare", "Quando vuole afferrare una creatura o lottare con essa, il personaggio può usare l'azione di Attacco per effettuare un attacco in mischia speciale: una presa. Se può effettuare più attacchi con l'azione di Attacco, la presa sostituisce uno di essi.\n\nIl bersaglio della presa deve essere al massimo di una taglia più grande del personaggio e trovarsi entro la sua portata. Usando almeno una mano libera, il personaggio cerca di afferrarlo effettuando una prova di presa invece di un tiro per colpire: una prova di Forza (Atletica) contrapposta alla prova di Forza (Atletica) o di Destrezza (Acrobazia) del bersaglio (a scelta del bersaglio). Se vince, il bersaglio ottiene la condizione di afferrato. La condizione indica cosa le pone fine, e il personaggio può liberare il bersaglio quando vuole (non richiede alcuna azione).\n\n**Liberarsi da una presa.** Una creatura afferrata può usare la sua azione per liberarsi. Per riuscirci deve superare una prova di Forza (Atletica) o di Destrezza (Acrobazia) contrapposta alla prova di Forza (Atletica) di chi la afferra.\n\n**Spostare una creatura afferrata.** Quando si muove, il personaggio può trascinare o trasportare con sé la creatura afferrata, ma la sua velocità è dimezzata, a meno che la creatura non sia di due o più taglie più piccola di lui.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "shoving-a-creature", RuleCategory.Rule,
			related: new[] { "prone", "grappling" },
			en: ("Shoving a Creature", "Using the Attack action, you can make a special melee attack to shove a creature, either to knock it prone or push it away from you. If you're able to make multiple attacks with the Attack action, this attack replaces one of them.\n\nThe target must be no more than one size larger than you and must be within your reach. Instead of making an attack roll, you make a Strength (Athletics) check contested by the target's Strength (Athletics) or Dexterity (Acrobatics) check (the target chooses the ability to use). If you win the contest, you either knock the target prone or push it 5 feet away from you.",
				new[] { "shove" }),
			it: ("Spingere una creatura", "Con l'azione di Attacco, il personaggio può effettuare un attacco in mischia speciale per spingere una creatura, buttandola a terra prona o allontanandola da sé. Se può effettuare più attacchi con l'azione di Attacco, la spinta sostituisce uno di essi.\n\nIl bersaglio deve essere al massimo di una taglia più grande del personaggio e trovarsi entro la sua portata. Invece di un tiro per colpire, il personaggio effettua una prova di Forza (Atletica) contrapposta alla prova di Forza (Atletica) o di Destrezza (Acrobazia) del bersaglio (a scelta del bersaglio). Se vince la contesa, butta a terra il bersaglio rendendolo prono, oppure lo spinge di 1,5 metri lontano da sé.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "cover", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Cover", "Walls, trees, creatures, and other obstacles can provide cover during combat, making a target more difficult to harm. A target can benefit from cover only when an attack or other effect originates on the opposite side of the cover.\n\nThere are three degrees of cover. If a target is behind multiple sources of cover, only the most protective degree of cover applies; the degrees aren't added together. For example, if a target is behind a creature that gives half cover and a tree trunk that gives three-quarters cover, the target has three-quarters cover.\n\nA target with **half cover** has a +2 bonus to AC and Dexterity saving throws. A target has half cover if an obstacle blocks at least half of its body. The obstacle might be a low wall, a large piece of furniture, a narrow tree trunk, or a creature, whether that creature is an enemy or a friend.\n\nA target with **three-quarters cover** has a +5 bonus to AC and Dexterity saving throws. A target has three-quarters cover if about three-quarters of it is covered by an obstacle. The obstacle might be a portcullis, an arrow slit, or a thick tree trunk.\n\nA target with **total cover** can't be targeted directly by an attack or a spell, although some spells can reach such a target by including it in an area of effect. A target has total cover if it is completely concealed by an obstacle.",
				new[] { "half cover", "three-quarters cover", "total cover" }),
			it: ("Copertura", "Muri, alberi, creature e altri ostacoli possono offrire copertura durante il combattimento, rendendo più difficile ferire un bersaglio. Un bersaglio beneficia della copertura solo se l'attacco o l'effetto proviene dal lato opposto della copertura.\n\nEsistono tre gradi di copertura. Se un bersaglio si trova dietro più fonti di copertura, si applica soltanto il grado più protettivo: i gradi non si sommano. Per esempio, se un bersaglio si trova dietro una creatura che offre mezza copertura e dietro un tronco d'albero che offre tre quarti di copertura, ha tre quarti di copertura.\n\nUn bersaglio con **mezza copertura** ottiene un bonus di +2 alla CA e ai tiri salvezza su Destrezza. Ha mezza copertura se un ostacolo gli copre almeno metà del corpo: un muretto, un mobile ingombrante, un tronco sottile o una creatura, amica o nemica che sia.\n\nUn bersaglio con **tre quarti di copertura** ottiene un bonus di +5 alla CA e ai tiri salvezza su Destrezza. Ha tre quarti di copertura se un ostacolo gliene copre circa tre quarti: una saracinesca, una feritoia o un tronco spesso.\n\nUn bersaglio con **copertura totale** non può essere preso di mira direttamente da un attacco o da un incantesimo, anche se alcuni incantesimi possono raggiungerlo includendolo in un'area di effetto. Ha copertura totale se un ostacolo lo nasconde completamente.",
				new[] { "mezza copertura", "tre quarti di copertura", "copertura dei tre quarti", "copertura totale" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "hit-points", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Hit Points", "Hit points represent a combination of physical and mental durability, the will to live, and luck. Creatures with more hit points are more difficult to kill. Those with fewer hit points are more fragile.\n\nA creature's current hit points (usually just called hit points) can be any number from the creature's hit point maximum down to 0. This number changes frequently as a creature takes damage or receives healing.\n\nWhenever a creature takes damage, that damage is subtracted from its hit points. The loss of hit points has no effect on a creature's capabilities until the creature drops to 0 hit points.",
				Array.Empty<string>()),
			it: ("Punti ferita", "I punti ferita rappresentano una combinazione di resistenza fisica e mentale, volontà di vivere e fortuna. Le creature con più punti ferita sono più difficili da uccidere, quelle con meno sono più fragili.\n\nI punti ferita attuali di una creatura (di solito chiamati semplicemente punti ferita) possono assumere qualsiasi valore compreso tra il suo massimo di punti ferita e 0. Questo numero cambia spesso, man mano che la creatura subisce danni o riceve guarigione.\n\nOgni volta che una creatura subisce danni, questi vengono sottratti ai suoi punti ferita. Perdere punti ferita non ha alcun effetto sulle capacità della creatura finché non scende a 0 punti ferita.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "damage-rolls", RuleCategory.Rule,
			related: new[] { "critical-hits", "damage-types" },
			en: ("Damage Rolls", "Each weapon, spell, and harmful monster ability specifies the damage it deals. You roll the damage die or dice, add any modifiers, and apply the damage to your target. Magic weapons, special abilities, and other factors can grant a bonus to damage. With a penalty, it is possible to deal 0 damage, but never negative damage.\n\nWhen attacking with a **weapon**, you add your ability modifier—the same modifier used for the attack roll-to the damage. A **spell** tells you which dice to roll for damage and whether to add any modifiers.\n\nIf a spell or other effect deals damage to **more than one target** at the same time, roll the damage once for all of them. For example, when a wizard casts _fireball_ or a cleric casts _flame strike_, the spell's damage is rolled once for all creatures caught in the blast.",
				Array.Empty<string>()),
			it: ("Tiri per i danni", "Ogni arma, incantesimo e capacità dannosa di un mostro indica i danni che infligge. Si tirano il dado o i dadi dei danni, si aggiungono gli eventuali modificatori e si applicano i danni al bersaglio. Armi magiche, capacità speciali e altri fattori possono concedere un bonus ai danni. Con una penalità si possono infliggere 0 danni, ma mai danni negativi.\n\nQuando attacca con un'**arma**, il personaggio aggiunge ai danni il suo modificatore di caratteristica, lo stesso usato per il tiro per colpire. Un **incantesimo** indica quali dadi tirare per i danni e se aggiungere dei modificatori.\n\nSe un incantesimo o un altro effetto infligge danni a **più bersagli** contemporaneamente, i danni si tirano una sola volta per tutti. Per esempio, quando un mago lancia _Palla di Fuoco_ o un chierico lancia _Colpo Infuocato_, i danni dell'incantesimo si tirano una volta sola per tutte le creature colpite dall'esplosione.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "critical-hits", RuleCategory.Rule,
			related: new[] { "attack-rolls" },
			en: ("Critical Hits", "When you score a critical hit, you get to roll extra dice for the attack's damage against the target. Roll all of the attack's damage dice twice and add them together. Then add any relevant modifiers as normal. To speed up play, you can roll all the damage dice at once.\n\nFor example, if you score a critical hit with a dagger, roll 2d4 for the damage, rather than 1d4, and then add your relevant ability modifier. If the attack involves other damage dice, such as from the rogue's Sneak Attack feature, you roll those dice twice as well.",
				new[] { "critical hit", "critical hits" }),
			it: ("Colpi critici", "Quando mette a segno un colpo critico, il personaggio può tirare dadi aggiuntivi per i danni dell'attacco contro il bersaglio: tira due volte tutti i dadi dei danni dell'attacco e li somma, poi aggiunge normalmente i modificatori pertinenti. Per velocizzare il gioco, si possono tirare tutti i dadi dei danni insieme.\n\nPer esempio, con un colpo critico inferto con un pugnale si tirano 2d4 danni invece di 1d4, poi si aggiunge il modificatore di caratteristica pertinente. Se l'attacco prevede altri dadi di danno, come quelli del privilegio Attacco Furtivo del ladro, anche quelli si tirano due volte.",
				new[] { "colpo critico", "colpi critici" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "damage-types", RuleCategory.Rule,
			related: new[] { "damage-resistance-and-vulnerability" },
			en: ("Damage Types", "Different attacks, damaging spells, and other harmful effects deal different types of damage. Damage types have no rules of their own, but other rules, such as damage resistance, rely on the types.\n\nThe damage types follow, with examples to help a GM assign a damage type to a new effect.\n\n**Acid.** The corrosive spray of a black dragon's breath and the dissolving enzymes secreted by a black pudding deal acid damage.\n\n**Bludgeoning.** Blunt force attacks—hammers, falling, constriction, and the like-deal bludgeoning damage.\n\n**Cold.** The infernal chill radiating from an ice devil's spear and the frigid blast of a white dragon's breath deal cold damage.\n\n**Fire.** Red dragons breathe fire, and many spells conjure flames to deal fire damage.\n\n**Force.** Force is pure magical energy focused into a damaging form. Most effects that deal force damage are spells, including _magic missile_ and _spiritual weapon_.\n\n**Lightning.** A _lightning bolt_ spell and a blue dragon's breath deal lightning damage.\n\n**Necrotic.** Necrotic damage, dealt by certain undead and a spell such as _chill touch_, withers matter and even the soul.\n\n**Piercing.** Puncturing and impaling attacks, including spears and monsters' bites, deal piercing damage.\n\n**Poison.** Venomous stings and the toxic gas of a green dragon's breath deal poison damage.\n\n**Psychic.** Mental abilities such as a mind flayer's psionic blast deal psychic damage.\n\n**Radiant.** Radiant damage, dealt by a cleric's _flame strike_ spell or an angel's smiting weapon, sears the flesh like fire and overloads the spirit with power.\n\n**Slashing.** Swords, axes, and monsters' claws deal slashing damage.\n\n**Thunder.** A concussive burst of sound, such as the effect of the _thunderwave_ spell, deals thunder damage.",
				Array.Empty<string>()),
			it: ("Tipi di danno", "Attacchi, incantesimi dannosi e altri effetti nocivi infliggono danni di tipi diversi. I tipi di danno non hanno regole proprie, ma altre regole, come la resistenza ai danni, si basano su di essi.\n\nEcco i tipi di danno, con alcuni esempi che aiutano il DM ad assegnare un tipo di danno a un nuovo effetto.\n\n**Acido.** Il getto corrosivo del soffio di un drago nero e gli enzimi dissolventi secreti da un budino nero infliggono danni da acido.\n\n**Contundente.** Gli attacchi con forza d'urto (martelli, cadute, stritolamenti e simili) infliggono danni contundenti.\n\n**Freddo.** Il gelo infernale che si irradia dalla lancia di un diavolo del ghiaccio e il soffio gelido di un drago bianco infliggono danni da freddo.\n\n**Fuoco.** I draghi rossi soffiano fuoco, e molti incantesimi evocano fiamme che infliggono danni da fuoco.\n\n**Forza.** La forza è pura energia magica concentrata in una forma dannosa. La maggior parte degli effetti che infliggono danni da forza sono incantesimi, come _Dardo Incantato_ e _Arma Spirituale_.\n\n**Fulmine.** L'incantesimo _Fulmine_ e il soffio di un drago blu infliggono danni da fulmine.\n\n**Necrotico.** I danni necrotici, inflitti da certi non morti e da incantesimi come _Tocco Gelido_, avvizziscono la materia e persino l'anima.\n\n**Perforante.** Gli attacchi che trafiggono e impalano, come quelli con le lance e i morsi dei mostri, infliggono danni perforanti.\n\n**Veleno.** I pungiglioni velenosi e il gas tossico del soffio di un drago verde infliggono danni da veleno.\n\n**Psichico.** Le capacità mentali, come la scarica psionica di un mind flayer, infliggono danni psichici.\n\n**Radioso.** I danni radiosi, inflitti dall'incantesimo _Colpo Infuocato_ di un chierico o dall'arma punitrice di un angelo, bruciano la carne come il fuoco e sovraccaricano lo spirito di energia.\n\n**Tagliente.** Spade, asce e artigli dei mostri infliggono danni taglienti.\n\n**Tuono.** Un'esplosione di suono assordante, come l'effetto dell'incantesimo _Onda Tonante_, infligge danni da tuono.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "damage-resistance-and-vulnerability", RuleCategory.Rule,
			related: new[] { "damage-types" },
			en: ("Damage Resistance and Vulnerability", "Some creatures and objects are exceedingly difficult or unusually easy to hurt with certain types of damage.\n\nIf a creature or an object has **resistance** to a damage type, damage of that type is halved against it. If a creature or an object has **vulnerability** to a damage type, damage of that type is doubled against it.\n\nResistance and then vulnerability are applied after all other modifiers to damage. For example, a creature has resistance to bludgeoning damage and is hit by an attack that deals 25 bludgeoning damage. The creature is also within a magical aura that reduces all damage by 5. The 25 damage is first reduced by 5 and then halved, so the creature takes 10 damage.\n\nMultiple instances of resistance or vulnerability that affect the same damage type count as only one instance. For example, if a creature has resistance to fire damage as well as resistance to all nonmagical damage, the damage of a nonmagical fire is reduced by half against the creature, not reduced by three-quarters.",
				new[] { "resistance", "vulnerability" }),
			it: ("Resistenza e vulnerabilità ai danni", "Alcune creature e alcuni oggetti sono estremamente difficili, o insolitamente facili, da ferire con certi tipi di danno.\n\nSe una creatura o un oggetto ha **resistenza** a un tipo di danno, i danni di quel tipo che subisce sono dimezzati. Se ha **vulnerabilità** a un tipo di danno, i danni di quel tipo che subisce sono raddoppiati.\n\nResistenza e vulnerabilità si applicano, in quest'ordine, dopo tutti gli altri modificatori ai danni. Per esempio, una creatura con resistenza ai danni contundenti viene colpita da un attacco che infligge 25 danni contundenti mentre si trova in un'aura magica che riduce tutti i danni di 5: i 25 danni vengono prima ridotti di 5 e poi dimezzati, quindi la creatura subisce 10 danni.\n\nPiù istanze di resistenza o di vulnerabilità che riguardano lo stesso tipo di danno contano come una sola. Per esempio, se una creatura ha resistenza ai danni da fuoco e anche resistenza a tutti i danni non magici, i danni di un fuoco non magico vengono dimezzati, non ridotti di tre quarti.",
				new[] { "resistenza", "vulnerabilità" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "healing", RuleCategory.Rule,
			related: new[] { "hit-points" },
			en: ("Healing", "Unless it results in death, damage isn't permanent. Even death is reversible through powerful magic. Rest can restore a creature's hit points, and magical methods such as a _cure wounds_ spell or a _potion of healing_ can remove damage in an instant.\n\nWhen a creature receives healing of any kind, hit points regained are added to its current hit points. A creature's hit points can't exceed its hit point maximum, so any hit points regained in excess of this number are lost. For example, a druid grants a ranger 8 hit points of healing. If the ranger has 14 current hit points and has a hit point maximum of 20, the ranger regains 6 hit points from the druid, not 8.\n\nA creature that has died can't regain hit points until magic such as the _revivify_ spell has restored it to life.",
				Array.Empty<string>()),
			it: ("Guarigione", "I danni non sono permanenti, a meno che non causino la morte, e persino la morte può essere annullata da una magia potente. Il riposo può ripristinare i punti ferita di una creatura, e metodi magici come l'incantesimo _Cura Ferite_ o una _pozione di guarigione_ possono rimuovere i danni in un istante.\n\nQuando una creatura riceve una guarigione di qualsiasi tipo, i punti ferita recuperati si sommano ai suoi punti ferita attuali. I punti ferita di una creatura non possono superare il suo massimo, quindi quelli recuperati in eccesso vanno perduti. Per esempio, un druido concede 8 punti ferita di guarigione a un ranger: se il ranger ha 14 punti ferita attuali e un massimo di 20, recupera 6 punti ferita, non 8.\n\nUna creatura morta non può recuperare punti ferita finché una magia come l'incantesimo _Rinascita_ non l'ha riportata in vita.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "instant-death", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Instant Death", "Massive damage can kill you instantly. When damage reduces you to 0 hit points and there is damage remaining, you die if the remaining damage equals or exceeds your hit point maximum.\n\nFor example, a cleric with a maximum of 12 hit points currently has 6 hit points. If she takes 18 damage from an attack, she is reduced to 0 hit points, but 12 damage remains. Because the remaining damage equals her hit point maximum, the cleric dies.",
				Array.Empty<string>()),
			it: ("Morte istantanea", "Danni ingenti possono uccidere sul colpo. Quando i danni riducono il personaggio a 0 punti ferita e ne avanzano ancora, il personaggio muore se i danni rimanenti sono pari o superiori al suo massimo di punti ferita.\n\nPer esempio, una chierica con un massimo di 12 punti ferita ne ha attualmente 6. Se subisce 18 danni da un attacco, scende a 0 punti ferita e avanzano 12 danni: poiché i danni rimanenti sono pari al suo massimo di punti ferita, la chierica muore.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "death-saving-throws", RuleCategory.Rule,
			related: new[] { "stabilizing-a-creature", "instant-death" },
			en: ("Death Saving Throws", "Whenever you start your turn with 0 hit points, you must make a special saving throw, called a death saving throw, to determine whether you creep closer to death or hang onto life. Unlike other saving throws, this one isn't tied to any ability score. You are in the hands of fate now, aided only by spells and features that improve your chances of succeeding on a saving throw.\n\nRoll a d20. If the roll is 10 or higher, you succeed. Otherwise, you fail. A success or failure has no effect by itself. On your third success, you become stable (see below). On your third failure, you die. The successes and failures don't need to be consecutive; keep track of both until you collect three of a kind. The number of both is reset to zero when you regain any hit points or become stable.\n\n**Rolling 1 or 20.** When you make a death saving throw and roll a 1 on the d20, it counts as two failures. If you roll a 20 on the d20, you regain 1 hit point.\n\n**Damage at 0 Hit Points.** If you take any damage while you have 0 hit points, you suffer a death saving throw failure. If the damage is from a critical hit, you suffer two failures instead. If the damage equals or exceeds your hit point maximum, you suffer instant death.",
				new[] { "death saving throw", "death saving throws" }),
			it: ("Tiri salvezza contro morte", "Ogni volta che inizia il suo turno con 0 punti ferita, il personaggio deve effettuare un tiro salvezza speciale, chiamato tiro salvezza contro morte, per stabilire se si avvicina alla morte o se resta aggrappato alla vita. A differenza degli altri tiri salvezza, questo non è legato ad alcun punteggio di caratteristica: il personaggio è nelle mani del destino, aiutato soltanto dagli incantesimi e dai privilegi che migliorano le probabilità di superare un tiro salvezza.\n\nSi tira un d20: con 10 o più il tiro riesce, altrimenti fallisce. Un successo o un fallimento, di per sé, non ha effetto. Al terzo successo il personaggio diventa stabile (vedi sotto); al terzo fallimento muore. Successi e fallimenti non devono essere consecutivi: si tiene il conto di entrambi finché non se ne accumulano tre dello stesso tipo. Entrambi i conteggi si azzerano quando il personaggio recupera punti ferita o diventa stabile.\n\n**Ottenere 1 o 20.** Se nel tiro salvezza contro morte il d20 dà 1, conta come due fallimenti. Se dà 20, il personaggio recupera 1 punto ferita.\n\n**Danni a 0 punti ferita.** Se subisce danni mentre ha 0 punti ferita, il personaggio subisce un fallimento al tiro salvezza contro morte; se i danni provengono da un colpo critico, subisce invece due fallimenti. Se i danni sono pari o superiori al suo massimo di punti ferita, muore all'istante.",
				new[] { "tiro salvezza contro morte", "tiri salvezza contro morte", "tiro salvezza contro la morte", "tiri salvezza contro la morte" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "stabilizing-a-creature", RuleCategory.Rule,
			related: new[] { "death-saving-throws" },
			en: ("Stabilizing a Creature", "The best way to save a creature with 0 hit points is to heal it. If healing is unavailable, the creature can at least be stabilized so that it isn't killed by a failed death saving throw.\n\nYou can use your action to administer first aid to an unconscious creature and attempt to stabilize it, which requires a successful DC 10 Wisdom (Medicine) check.\n\nA **stable** creature doesn't make death saving throws, even though it has 0 hit points, but it does remain unconscious. The creature stops being stable, and must start making death saving throws again, if it takes any damage. A stable creature that isn't healed regains 1 hit point after 1d4 hours.",
				new[] { "stable", "stabilize" }),
			it: ("Stabilizzare una creatura", "Il modo migliore per salvare una creatura a 0 punti ferita è curarla. Se non è possibile, la si può almeno stabilizzare, in modo che non muoia per un tiro salvezza contro morte fallito.\n\nIl personaggio può usare la sua azione per prestare il primo soccorso a una creatura priva di sensi e cercare di stabilizzarla, superando una prova di Saggezza (Medicina) con CD 10.\n\nUna creatura **stabile** non effettua tiri salvezza contro morte, anche se ha 0 punti ferita, ma resta priva di sensi. Se subisce danni smette di essere stabile e deve ricominciare a effettuare tiri salvezza contro morte. Una creatura stabile che non riceve cure recupera 1 punto ferita dopo 1d4 ore.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "knocking-a-creature-out", RuleCategory.Rule,
			related: new[] { "unconscious" },
			en: ("Knocking a Creature Out", "Sometimes an attacker wants to incapacitate a foe, rather than deal a killing blow. When an attacker reduces a creature to 0 hit points with a melee attack, the attacker can knock the creature out. The attacker can make this choice the instant the damage is dealt. The creature falls unconscious and is stable.",
				Array.Empty<string>()),
			it: ("Tramortire una creatura", "A volte un attaccante vuole rendere inoffensivo un nemico invece di infliggergli il colpo di grazia. Quando riduce una creatura a 0 punti ferita con un attacco in mischia, l'attaccante può tramortirla, decidendolo nel momento in cui infligge i danni. La creatura cade priva di sensi ed è stabile.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "temporary-hit-points", RuleCategory.Rule,
			related: new[] { "hit-points" },
			en: ("Temporary Hit Points", "Some spells and special abilities confer temporary hit points to a creature. Temporary hit points aren't actual hit points; they are a buffer against damage, a pool of hit points that protect you from injury.\n\nWhen you have temporary hit points and take damage, the temporary hit points are lost first, and any leftover damage carries over to your normal hit points. For example, if you have 5 temporary hit points and take 7 damage, you lose the temporary hit points and then take 2 damage.\n\nBecause temporary hit points are separate from your actual hit points, they can exceed your hit point maximum. A character can, therefore, be at full hit points and receive temporary hit points.\n\nHealing can't restore temporary hit points, and they can't be added together. If you have temporary hit points and receive more of them, you decide whether to keep the ones you have or to gain the new ones. For example, if a spell grants you 12 temporary hit points when you already have 10, you can have 12 or 10, not 22.\n\nIf you have 0 hit points, receiving temporary hit points doesn't restore you to consciousness or stabilize you. They can still absorb damage directed at you while you're in that state, but only true healing can save you.\n\nUnless a feature that grants you temporary hit points has a duration, they last until they're depleted or you finish a long rest.",
				new[] { "temporary hit points", "temporary hit point" }),
			it: ("Punti ferita temporanei", "Alcuni incantesimi e capacità speciali conferiscono punti ferita temporanei a una creatura. I punti ferita temporanei non sono veri punti ferita: sono un cuscinetto contro i danni, una riserva di punti ferita che protegge dalle ferite.\n\nQuando il personaggio ha punti ferita temporanei e subisce danni, perde prima quelli temporanei, e gli eventuali danni rimanenti si applicano ai suoi punti ferita normali. Per esempio, se ha 5 punti ferita temporanei e subisce 7 danni, perde i punti ferita temporanei e poi subisce 2 danni.\n\nPoiché sono separati dai punti ferita veri e propri, i punti ferita temporanei possono superare il massimo dei punti ferita: un personaggio può quindi avere tutti i suoi punti ferita e ricevere comunque punti ferita temporanei.\n\nLa guarigione non ripristina i punti ferita temporanei, che non si sommano tra loro. Se il personaggio ha punti ferita temporanei e ne riceve altri, decide se tenere quelli che ha o prendere i nuovi. Per esempio, se un incantesimo gli concede 12 punti ferita temporanei quando ne ha già 10, può averne 12 o 10, non 22.\n\nSe ha 0 punti ferita, ricevere punti ferita temporanei non gli fa riprendere i sensi né lo stabilizza. Possono comunque assorbire i danni diretti a lui mentre si trova in quello stato, ma solo una vera guarigione può salvarlo.\n\nSalvo che il privilegio che li concede abbia una durata, i punti ferita temporanei durano finché non si esauriscono o finché il personaggio non completa un riposo lungo.",
				new[] { "punti ferita temporanei", "punto ferita temporaneo" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "mounted-combat", RuleCategory.Rule,
			related: new[] { "opportunity-attacks" },
			en: ("Mounted Combat", "A knight charging into battle on a warhorse, a wizard casting spells from the back of a griffon, or a cleric soaring through the sky on a pegasus all enjoy the benefits of speed and mobility that a mount can provide.\n\nA willing creature that is at least one size larger than you and that has an appropriate anatomy can serve as a mount, using the following rules.\n\n**Mounting and Dismounting**\n\nOnce during your move, you can mount a creature that is within 5 feet of you or dismount. Doing so costs an amount of movement equal to half your speed. For example, if your speed is 30 feet, you must spend 15 feet of movement to mount a horse. Therefore, you can't mount it if you don't have 15 feet of movement left or if your speed is 0.\n\nIf an effect moves your mount against its will while you're on it, you must succeed on a DC 10 Dexterity saving throw or fall off the mount, landing prone in a space within 5 feet of it. If you're knocked prone while mounted, you must make the same saving throw.\n\nIf your mount is knocked prone, you can use your reaction to dismount it as it falls and land on your feet. Otherwise, you are dismounted and fall prone in a space within 5 feet it.\n\n**Controlling a Mount**\n\nWhile you're mounted, you have two options. You can either control the mount or allow it to act independently. Intelligent creatures, such as dragons, act independently.\n\nYou can control a mount only if it has been trained to accept a rider. Domesticated horses, donkeys, and similar creatures are assumed to have such training. The initiative of a controlled mount changes to match yours when you mount it. It moves as you direct it, and it has only three action options: Dash, Disengage, and Dodge. A controlled mount can move and act even on the turn that you mount it.\n\nAn independent mount retains its place in the initiative order. Bearing a rider puts no restrictions on the actions the mount can take, and it moves and acts as it wishes. It might flee from combat, rush to attack and devour a badly injured foe, or otherwise act against your wishes.\n\nIn either case, if the mount provokes an opportunity attack while you're on it, the attacker can target you or the mount.",
				Array.Empty<string>()),
			it: ("Combattere in sella", "Un cavaliere che si lancia in battaglia su un cavallo da guerra, un mago che lancia incantesimi dal dorso di un grifone o un chierico che solca il cielo in groppa a un pegaso godono tutti della velocità e della mobilità che una cavalcatura può offrire.\n\nUna creatura consenziente, almeno di una taglia più grande del personaggio e con una conformazione adatta, può fungere da cavalcatura secondo le regole seguenti.\n\n**Montare e smontare**\n\nUna volta durante il suo movimento, il personaggio può montare su una creatura entro 1,5 metri da lui oppure smontare. Farlo costa una quantità di movimento pari a metà della sua velocità: per esempio, se la sua velocità è di 9 metri, deve spendere 4,5 metri di movimento per montare a cavallo. Non può quindi montare se non gli restano 4,5 metri di movimento o se la sua velocità è 0.\n\nSe un effetto sposta la sua cavalcatura contro la volontà di quest'ultima mentre il personaggio è in sella, il personaggio deve superare un tiro salvezza su Destrezza con CD 10, altrimenti cade dalla cavalcatura e atterra prono in uno spazio entro 1,5 metri da essa. Deve effettuare lo stesso tiro salvezza se viene reso prono mentre è in sella.\n\nSe la sua cavalcatura viene resa prona, il personaggio può usare la sua reazione per smontare mentre cade e atterrare in piedi; altrimenti viene disarcionato e cade prono in uno spazio entro 1,5 metri da essa.\n\n**Controllare una cavalcatura**\n\nMentre è in sella, il personaggio ha due opzioni: controllare la cavalcatura o lasciarla agire in modo indipendente. Le creature intelligenti, come i draghi, agiscono in modo indipendente.\n\nPuò controllare una cavalcatura solo se è stata addestrata ad accettare un cavaliere; si presume che cavalli, asini e creature simili addomesticati abbiano questo addestramento. Quando il personaggio monta in sella, l'iniziativa di una cavalcatura controllata diventa uguale alla sua. La cavalcatura si muove come lui la guida e può effettuare soltanto tre azioni: Scatto, Disimpegno e Schivata. Una cavalcatura controllata può muoversi e agire anche nel turno in cui il personaggio monta in sella.\n\nUna cavalcatura indipendente mantiene il suo posto nell'ordine di iniziativa. Portare un cavaliere non limita le azioni che può effettuare: si muove e agisce come preferisce, e potrebbe fuggire dal combattimento, lanciarsi ad attaccare e divorare un nemico gravemente ferito o agire comunque contro la volontà del personaggio.\n\nIn entrambi i casi, se la cavalcatura provoca un attacco di opportunità mentre il personaggio è in sella, l'attaccante può scegliere come bersaglio il personaggio o la cavalcatura.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "underwater-combat", RuleCategory.Rule,
			related: new[] { "ranged-attacks" },
			en: ("Underwater Combat", "When adventurers pursue sahuagin back to their undersea homes, fight off sharks in an ancient shipwreck, or find themselves in a flooded dungeon room, they must fight in a challenging environment. Underwater the following rules apply.\n\nWhen making a **melee weapon attack**, a creature that doesn't have a swimming speed (either natural or granted by magic) has disadvantage on the attack roll unless the weapon is a dagger, javelin, shortsword, spear, or trident.\n\nA **ranged weapon attack** automatically misses a target beyond the weapon's normal range. Even against a target within normal range, the attack roll has disadvantage unless the weapon is a crossbow, a net, or a weapon that is thrown like a javelin (including a spear, trident, or dart).\n\nCreatures and objects that are fully immersed in water have resistance to fire damage.",
				Array.Empty<string>()),
			it: ("Combattere sott'acqua", "Quando gli avventurieri inseguono i sahuagin fino alle loro dimore sottomarine, respingono gli squali in un antico relitto o si ritrovano in una stanza allagata di un dungeon, devono combattere in un ambiente ostile. Sott'acqua si applicano le regole seguenti.\n\nQuando effettua un **attacco con un'arma da mischia**, una creatura priva di velocità di nuoto (naturale o concessa dalla magia) subisce svantaggio al tiro per colpire, a meno che l'arma non sia un pugnale, un giavellotto, una spada corta, una lancia o un tridente.\n\nUn **attacco con un'arma a distanza** manca automaticamente un bersaglio oltre la gittata normale dell'arma. Anche contro un bersaglio entro la gittata normale, il tiro per colpire subisce svantaggio, a meno che l'arma non sia una balestra, una rete o un'arma da lancio come il giavellotto (inclusi lancia, tridente e dardo).\n\nLe creature e gli oggetti completamente immersi nell'acqua hanno resistenza ai danni da fuoco.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "climbing-swimming-and-crawling", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Climbing, Swimming, and Crawling", "While climbing or swimming, each foot of movement costs 1 extra foot (2 extra feet in difficult terrain), unless a creature has a climbing or swimming speed. At the GM's option, climbing a slippery vertical surface or one with few handholds requires a successful Strength (Athletics) check. Similarly, gaining any distance in rough water might require a successful Strength (Athletics) check.",
				Array.Empty<string>()),
			it: ("Scalare, nuotare e strisciare", "Mentre scala o nuota, ogni metro di movimento costa al personaggio 1 metro in più (2 metri in più su terreno difficile), a meno che non abbia una velocità di scalata o di nuoto. A discrezione del DM, scalare una superficie verticale scivolosa o con pochi appigli richiede una prova di Forza (Atletica) superata; allo stesso modo, avanzare in acque agitate potrebbe richiedere una prova di Forza (Atletica) superata.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "jumping", RuleCategory.Rule,
			related: new[] { "climbing-swimming-and-crawling" },
			en: ("Jumping", "Your Strength determines how far you can jump.\n\n**Long Jump.** When you make a long jump, you cover a number of feet up to your Strength score if you move at least 10 feet on foot immediately before the jump. When you make a standing long jump, you can leap only half that distance. Either way, each foot you clear on the jump costs a foot of movement.\n\nThis rule assumes that the height of your jump doesn't matter, such as a jump across a stream or chasm. At your GM's option, you must succeed on a DC 10 Strength (Athletics) check to clear a low obstacle (no taller than a quarter of the jump's distance), such as a hedge or low wall. Otherwise, you hit it.\n\nWhen you land in difficult terrain, you must succeed on a DC 10 Dexterity (Acrobatics) check to land on your feet. Otherwise, you land prone.\n\n**High Jump.** When you make a high jump, you leap into the air a number of feet equal to 3 + your Strength modifier if you move at least 10 feet on foot immediately before the jump. When you make a standing high jump, you can jump only half that distance. Either way, each foot you clear on the jump costs a foot of movement. In some circumstances, your GM might allow you to make a Strength (Athletics) check to jump higher than you normally can.\n\nYou can extend your arms half your height above yourself during the jump. Thus, you can reach above you a distance equal to the height of the jump plus 1.5 times your height.",
				new[] { "long jump", "high jump" }),
			it: ("Saltare", "La Forza del personaggio determina quanto lontano può saltare.\n\n**Salto in lungo.** Con un salto in lungo, il personaggio copre fino a 30 centimetri per ogni punto del suo punteggio di Forza, se si muove di almeno 3 metri a piedi subito prima del salto. Da fermo può saltare solo la metà di quella distanza. In entrambi i casi, ogni metro superato con il salto costa un metro di movimento.\n\nQuesta regola presuppone che l'altezza del salto non conti, come quando si salta un ruscello o un crepaccio. A discrezione del DM, per superare un ostacolo basso (non più alto di un quarto della lunghezza del salto), come una siepe o un muretto, serve una prova di Forza (Atletica) con CD 10 superata; altrimenti il personaggio urta l'ostacolo.\n\nSe atterra su terreno difficile, deve superare una prova di Destrezza (Acrobazia) con CD 10 per atterrare in piedi; altrimenti atterra prono.\n\n**Salto in alto.** Con un salto in alto, il personaggio balza in aria per (3 + il suo modificatore di Forza) × 30 centimetri, se si muove di almeno 3 metri a piedi subito prima del salto. Da fermo può saltare solo la metà di quell'altezza. In entrambi i casi, ogni metro superato con il salto costa un metro di movimento. In alcune circostanze, il DM può permettergli di effettuare una prova di Forza (Atletica) per saltare più in alto del normale.\n\nDurante il salto può allungare le braccia sopra la testa per metà della sua altezza: può quindi raggiungere un'altezza pari a quella del salto più una volta e mezza la propria statura.",
				new[] { "salto in lungo", "salto in alto" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "falling", RuleCategory.Hazard,
			related: new[] { "prone" },
			en: ("Falling", "A fall from a great height is one of the most common hazards facing an adventurer. At the end of a fall, a creature takes 1d6 bludgeoning damage for every 10 feet it fell, to a maximum of 20d6. The creature lands prone, unless it avoids taking damage from the fall.",
				Array.Empty<string>()),
			it: ("Cadute", "Cadere da una grande altezza è uno dei pericoli più comuni per un avventuriero. Al termine della caduta, una creatura subisce 1d6 danni contundenti per ogni 3 metri di caduta, fino a un massimo di 20d6. La creatura atterra prona, a meno che non eviti di subire danni dalla caduta.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "suffocating", RuleCategory.Hazard,
			related: new[] { "death-saving-throws" },
			en: ("Suffocating", "A creature can hold its breath for a number of minutes equal to 1 + its Constitution modifier (minimum of 30 seconds).\n\nWhen a creature runs out of breath or is choking, it can survive for a number of rounds equal to its Constitution modifier (minimum of 1 round). At the start of its next turn, it drops to 0 hit points and is dying, and it can't regain hit points or be stabilized until it can breathe again.\n\nFor example, a creature with a Constitution of 14 can hold its breath for 3 minutes. If it starts suffocating, it has 2 rounds to reach air before it drops to 0 hit points.",
				Array.Empty<string>()),
			it: ("Soffocamento", "Una creatura può trattenere il respiro per un numero di minuti pari a 1 + il suo modificatore di Costituzione (minimo 30 secondi).\n\nQuando resta senza fiato o sta soffocando, una creatura può sopravvivere per un numero di round pari al suo modificatore di Costituzione (minimo 1 round). All'inizio del turno successivo scende a 0 punti ferita ed è morente, e non può recuperare punti ferita né essere stabilizzata finché non torna a respirare.\n\nPer esempio, una creatura con Costituzione 14 può trattenere il respiro per 3 minuti; se inizia a soffocare, ha 2 round per raggiungere l'aria prima di scendere a 0 punti ferita.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "vision-and-light", RuleCategory.Rule,
			related: new[] { "blinded", "blindsight", "darkvision", "truesight" },
			en: ("Vision and Light", "The most fundamental tasks of adventuring—noticing danger, finding hidden objects, hitting an enemy in combat, and targeting a spell, to name just a few—rely heavily on a character's ability to see. Darkness and other effects that obscure vision can prove a significant hindrance.\n\nA given area might be lightly or heavily obscured. In a **lightly obscured** area, such as dim light, patchy fog, or moderate foliage, creatures have disadvantage on Wisdom (Perception) checks that rely on sight.\n\nA **heavily obscured** area—such as darkness, opaque fog, or dense foliage-blocks vision entirely. A creature effectively suffers from the blinded condition when trying to see something in that area.\n\nThe presence or absence of light in an environment creates three categories of illumination: bright light, dim light, and darkness.\n\n**Bright light** lets most creatures see normally.\n\nEven gloomy days provide bright light, as do torches, lanterns, fires, and other sources of illumination within a specific radius.\n\n**Dim light**, also called shadows, creates a lightly obscured area. An area of dim light is usually a boundary between a source of bright light, such as a torch, and surrounding darkness. The soft light of twilight and dawn also counts as dim light. A particularly brilliant full moon might bathe the land in dim light.\n\n**Darkness** creates a heavily obscured area.\n\nCharacters face darkness outdoors at night (even most moonlit nights), within the confines of an unlit dungeon or a subterranean vault, or in an area of magical darkness.",
				new[] { "lightly obscured", "heavily obscured", "dim light", "bright light" }),
			it: ("Visione e illuminazione", "Le attività fondamentali di un avventuriero (notare un pericolo, trovare oggetti nascosti, colpire un nemico in combattimento e scegliere il bersaglio di un incantesimo, solo per citarne alcune) dipendono in gran parte dalla capacità di vedere. L'oscurità e gli altri effetti che ostacolano la vista possono rivelarsi un serio impedimento.\n\nUn'area può essere leggermente o pesantemente oscurata. In un'area **leggermente oscurata**, come una zona di luce fioca, di nebbia rada o di fogliame moderato, le creature subiscono svantaggio alle prove di Saggezza (Percezione) basate sulla vista.\n\nUn'area **pesantemente oscurata**, come una zona di oscurità, di nebbia fitta o di fogliame denso, blocca completamente la vista: una creatura che cerca di vedere qualcosa in quell'area subisce di fatto la condizione di accecato.\n\nLa presenza o l'assenza di luce in un ambiente crea tre categorie di illuminazione: luce intensa, luce fioca e oscurità.\n\nLa **luce intensa** permette alla maggior parte delle creature di vedere normalmente. Anche le giornate più cupe forniscono luce intensa, così come torce, lanterne, fuochi e altre fonti di illuminazione entro un certo raggio.\n\nLa **luce fioca**, detta anche penombra, crea un'area leggermente oscurata. Una zona di luce fioca di solito fa da confine tra una fonte di luce intensa, come una torcia, e l'oscurità circostante. Anche la luce tenue del crepuscolo e dell'alba conta come luce fioca, e una luna piena particolarmente splendente può bagnare il paesaggio di luce fioca.\n\nL'**oscurità** crea un'area pesantemente oscurata.\n\nI personaggi affrontano l'oscurità all'aperto di notte (anche nella maggior parte delle notti di luna), all'interno di un dungeon o di una cripta sotterranea priva di luci, o in un'area di oscurità magica.",
				new[] { "leggermente oscurato", "leggermente oscurata", "leggermente oscurati", "leggermente oscurate", "pesantemente oscurato", "pesantemente oscurata", "pesantemente oscurati", "pesantemente oscurate", "luce fioca", "luce intensa" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "blindsight", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Blindsight", "A creature with blindsight can perceive its surroundings without relying on sight, within a specific radius. Creatures without eyes, such as oozes, and creatures with echolocation or heightened senses, such as bats and true dragons, have this sense.",
				new[] { "blindsight" }),
			it: ("Vista cieca", "Una creatura con vista cieca può percepire ciò che la circonda entro un certo raggio senza fare affidamento sulla vista. Possiedono questo senso le creature prive di occhi, come le melme, e quelle dotate di ecolocalizzazione o di sensi acuiti, come i pipistrelli e i draghi veri.",
				new[] { "vista cieca" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "darkvision", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Darkvision", "Many creatures in fantasy gaming worlds, especially those that dwell underground, have darkvision. Within a specified range, a creature with darkvision can see in darkness as if the darkness were dim light, so areas of darkness are only lightly obscured as far as that creature is concerned. However, the creature can't discern color in darkness, only shades of gray.",
				new[] { "darkvision" }),
			it: ("Scurovisione", "Molte creature dei mondi fantasy, soprattutto quelle che vivono sottoterra, possiedono la scurovisione. Entro un certo raggio, una creatura con scurovisione vede nell'oscurità come se fosse luce fioca: per quella creatura, quindi, le aree di oscurità sono soltanto leggermente oscurate. Nell'oscurità non distingue i colori, ma solo sfumature di grigio.",
				new[] { "scurovisione" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "truesight", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Truesight", "A creature with truesight can, out to a specific range, see in normal and magical darkness, see invisible creatures and objects, automatically detect visual illusions and succeed on saving throws against them, and perceives the original form of a shapechanger or a creature that is transformed by magic. Furthermore, the creature can see into the Ethereal Plane.",
				new[] { "truesight" }),
			it: ("Vista pura", "Una creatura con vista pura, entro un certo raggio, vede nell'oscurità normale e magica, vede le creature e gli oggetti invisibili, individua automaticamente le illusioni visive e supera i tiri salvezza contro di esse, e percepisce la forma originale di un mutaforma o di una creatura trasformata dalla magia. Inoltre, può vedere nel Piano Etereo.",
				new[] { "vista pura" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "food-and-water", RuleCategory.Hazard,
			related: new[] { "exhaustion" },
			en: ("Food and Water", "Characters who don't eat or drink suffer the effects of exhaustion. Exhaustion caused by lack of food or water can't be removed until the character eats and drinks the full required amount.\n\n**Food**\n\nA character needs one pound of food per day and can make food last longer by subsisting on half rations. Eating half a pound of food in a day counts as half a day without food.\n\nA character can go without food for a number of days equal to 3 + his or her Constitution modifier (minimum 1). At the end of each day beyond that limit, a character automatically suffers one level of exhaustion.\n\nA normal day of eating resets the count of days without food to zero.\n\n**Water**\n\nA character needs one gallon of water per day, or two gallons per day if the weather is hot. A character who drinks only half that much water must succeed on a DC 15 Constitution saving throw or suffer one level of exhaustion at the end of the day. A character with access to even less water automatically suffers one level of exhaustion at the end of the day.\n\nIf the character already has one or more levels of exhaustion, the character takes two levels in either case.",
				Array.Empty<string>()),
			it: ("Cibo e acqua", "I personaggi che non mangiano o non bevono subiscono gli effetti dell'indebolimento. L'indebolimento causato dalla mancanza di cibo o di acqua non può essere rimosso finché il personaggio non mangia e beve tutta la quantità necessaria.\n\n**Cibo**\n\nUn personaggio ha bisogno di 0,5 kg di cibo al giorno e può far durare più a lungo le provviste nutrendosi a mezza razione: mangiare 250 grammi di cibo in un giorno conta come mezza giornata senza cibo.\n\nUn personaggio può restare senza cibo per un numero di giorni pari a 3 + il suo modificatore di Costituzione (minimo 1). Alla fine di ogni giorno oltre questo limite, subisce automaticamente un livello di indebolimento.\n\nUna normale giornata in cui si mangia riporta a zero il conteggio dei giorni senza cibo.\n\n**Acqua**\n\nUn personaggio ha bisogno di 4 litri d'acqua al giorno, o di 8 litri se fa caldo. Un personaggio che beve solo la metà di quella quantità deve superare un tiro salvezza su Costituzione con CD 15, altrimenti subisce un livello di indebolimento alla fine della giornata. Un personaggio che dispone di ancora meno acqua subisce automaticamente un livello di indebolimento alla fine della giornata.\n\nSe il personaggio ha già uno o più livelli di indebolimento, in entrambi i casi ne subisce due.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "short-rest", RuleCategory.Rule,
			related: new[] { "long-rest" },
			en: ("Short Rest", "A short rest is a period of downtime, at least 1 hour long, during which a character does nothing more strenuous than eating, drinking, reading, and tending to wounds.\n\nA character can spend one or more Hit Dice at the end of a short rest, up to the character's maximum number of Hit Dice, which is equal to the character's level. For each Hit Die spent in this way, the player rolls the die and adds the character's Constitution modifier to it. The character regains hit points equal to the total. The player can decide to spend an additional Hit Die after each roll. A character regains some spent Hit Dice upon finishing a long rest, as explained below.",
				new[] { "short rest", "short rests", "Hit Dice", "Hit Die" }),
			it: ("Riposo breve", "Un riposo breve è un periodo di inattività di almeno 1 ora durante il quale un personaggio non fa nulla di più faticoso che mangiare, bere, leggere e medicare le proprie ferite.\n\nAl termine di un riposo breve, un personaggio può spendere uno o più Dadi Vita, fino al suo numero massimo di Dadi Vita, che è pari al suo livello. Per ogni Dado Vita speso in questo modo, il giocatore tira il dado e aggiunge il modificatore di Costituzione del personaggio, che recupera un numero di punti ferita pari al totale. Dopo ogni tiro, il giocatore può decidere di spendere un altro Dado Vita. Un personaggio recupera parte dei Dadi Vita spesi completando un riposo lungo, come spiegato più avanti.",
				new[] { "riposo breve", "riposi brevi", "dadi vita", "dado vita" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "long-rest", RuleCategory.Rule,
			related: new[] { "short-rest" },
			en: ("Long Rest", "A long rest is a period of extended downtime, at least 8 hours long, during which a character sleeps or performs light activity: reading, talking, eating, or standing watch for no more than 2 hours. If the rest is interrupted by a period of strenuous activity—at least 1 hour of walking, fighting, casting spells, or similar adventuring activity-the characters must begin the rest again to gain any benefit from it.\n\nAt the end of a long rest, a character regains all lost hit points. The character also regains spent Hit Dice, up to a number of dice equal to half of the character's total number of them (minimum of one die). For example, if a character has eight Hit Dice, he or she can regain four spent Hit Dice upon finishing a long rest.\n\nA character can't benefit from more than one long rest in a 24-hour period, and a character must have at least 1 hit point at the start of the rest to gain its benefits.",
				new[] { "long rest", "long rests" }),
			it: ("Riposo lungo", "Un riposo lungo è un periodo di inattività prolungata, di almeno 8 ore, durante il quale un personaggio dorme o svolge attività leggere (leggere, parlare, mangiare o montare la guardia) per non più di 2 ore. Se il riposo viene interrotto da un periodo di attività faticosa (almeno 1 ora di cammino, combattimento, lancio di incantesimi o attività simili da avventurieri), i personaggi devono ricominciarlo da capo per trarne beneficio.\n\nAl termine di un riposo lungo, un personaggio recupera tutti i punti ferita perduti. Recupera anche i Dadi Vita spesi, fino a un numero pari alla metà del suo totale di Dadi Vita (minimo un dado). Per esempio, un personaggio con otto Dadi Vita può recuperarne fino a quattro spesi quando completa un riposo lungo.\n\nUn personaggio non può beneficiare di più di un riposo lungo nell'arco di 24 ore, e deve avere almeno 1 punto ferita all'inizio del riposo per ottenerne i benefici.",
				new[] { "riposo lungo", "riposi lunghi" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "cantrips", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Cantrips", "A cantrip is a spell that can be cast at will, without using a spell slot and without being prepared in advance. Repeated practice has fixed the spell in the caster's mind and infused the caster with the magic needed to produce the effect over and over. A cantrip's spell level is 0.",
				Array.Empty<string>()),
			it: ("Trucchetti", "Un trucchetto è un incantesimo che si può lanciare a volontà, senza usare uno slot incantesimo e senza prepararlo in anticipo. La pratica ripetuta lo ha fissato nella mente dell'incantatore e lo ha dotato della magia necessaria per produrne l'effetto più e più volte. Il livello di un trucchetto è 0.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "rituals", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Rituals", "Certain spells have a special tag: ritual. Such a spell can be cast following the normal rules for spellcasting, or the spell can be cast as a ritual. The ritual version of a spell takes 10 minutes longer to cast than normal. It also doesn't expend a spell slot, which means the ritual version of a spell can't be cast at a higher level.\n\nTo cast a spell as a ritual, a spellcaster must have a feature that grants the ability to do so. The cleric and the druid, for example, have such a feature. The caster must also have the spell prepared or on his or her list of spells known, unless the character's ritual feature specifies otherwise, as the wizard's does.",
				new[] { "ritual" }),
			it: ("Rituali", "Alcuni incantesimi hanno un'etichetta speciale: rituale. Un incantesimo del genere può essere lanciato seguendo le normali regole dell'incantamento oppure come rituale. La versione rituale richiede 10 minuti in più del normale per essere lanciata, ma non spende slot incantesimo: per questo non può essere lanciata a un livello superiore.\n\nPer lanciare un incantesimo come rituale, l'incantatore deve avere un privilegio che gliene conceda la capacità, come il chierico e il druido. Deve anche avere l'incantesimo preparato o tra i suoi incantesimi conosciuti, a meno che il suo privilegio rituale non dica altrimenti, come accade per il mago.",
				new[] { "rituale", "rituali" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "components", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Components", "A spell's components are the physical requirements you must meet in order to cast it. Each spell's description indicates whether it requires verbal (V), somatic (S), or material (M) components. If you can't provide one or more of a spell's components, you are unable to cast the spell.\n\n**Verbal (V)**\n\nMost spells require the chanting of mystic words. The words themselves aren't the source of the spell's power; rather, the particular combination of sounds, with specific pitch and resonance, sets the threads of magic in motion. Thus, a character who is gagged or in an area of silence, such as one created by the _silence_ spell, can't cast a spell with a verbal component.\n\n**Somatic (S)**\n\nSpellcasting gestures might include a forceful gesticulation or an intricate set of gestures. If a spell requires a somatic component, the caster must have free use of at least one hand to perform these gestures.\n\n**Material (M)**\n\nCasting some spells requires particular objects, specified in parentheses in the component entry. A character can use a **component pouch** or a **spellcasting focus** in place of the components specified for a spell. But if a cost is indicated for a component, a character must have that specific component before he or she can cast the spell.\n\nIf a spell states that a material component is consumed by the spell, the caster must provide this component for each casting of the spell.\n\nA spellcaster must have a hand free to access a spell's material components—or to hold a spellcasting focus-but it can be the same hand that he or she uses to perform somatic components.",
				new[] { "verbal component", "verbal components", "somatic component", "somatic components", "material component", "material components" }),
			it: ("Componenti", "Le componenti di un incantesimo sono i requisiti fisici da soddisfare per lanciarlo. La descrizione di ogni incantesimo indica se richiede componenti verbali (V), somatiche (S) o materiali (M). Se il personaggio non può fornire una o più componenti di un incantesimo, non può lanciarlo.\n\n**Verbale (V)**\n\nLa maggior parte degli incantesimi richiede di intonare parole mistiche. Non sono le parole in sé la fonte del potere dell'incantesimo, ma la particolare combinazione di suoni, con tono e risonanza specifici, che mette in moto i fili della magia. Un personaggio imbavagliato o in un'area di silenzio, come quella creata dall'incantesimo _Silenzio_, non può quindi lanciare un incantesimo con una componente verbale.\n\n**Somatica (S)**\n\nI gesti dell'incantamento possono essere movimenti energici o sequenze intricate. Se un incantesimo richiede una componente somatica, l'incantatore deve avere libera almeno una mano per eseguirli.\n\n**Materiale (M)**\n\nAlcuni incantesimi richiedono oggetti particolari, indicati tra parentesi nella voce delle componenti. Un personaggio può usare una **borsa per componenti** o un **focus da incantatore** al posto delle componenti indicate da un incantesimo; se però per una componente è indicato un costo, deve possedere proprio quella componente per lanciare l'incantesimo.\n\nSe un incantesimo dice che una componente materiale viene consumata, l'incantatore deve fornirla ogni volta che lo lancia.\n\nUn incantatore deve avere una mano libera per accedere alle componenti materiali di un incantesimo, o per impugnare un focus da incantatore, ma può essere la stessa mano che usa per le componenti somatiche.",
				new[] { "componente verbale", "componenti verbali", "componente somatica", "componenti somatiche", "componente materiale", "componenti materiali" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "concentration", RuleCategory.Rule,
			related: new[] { "incapacitated" },
			en: ("Concentration", "Some spells require you to maintain concentration in order to keep their magic active. If you lose concentration, such a spell ends.\n\nIf a spell must be maintained with concentration, that fact appears in its Duration entry, and the spell specifies how long you can concentrate on it. You can end concentration at any time (no action required).\n\nNormal activity, such as moving and attacking, doesn't interfere with concentration. The following factors can break concentration:\n- **Casting another spell that requires concentration.** You lose concentration on a spell if you cast another spell that requires concentration. You can't concentrate on two spells at once.\n- **Taking damage.** Whenever you take damage while you are concentrating on a spell, you must make a Constitution saving throw to maintain your concentration. The DC equals 10 or half the damage you take, whichever number is higher. If you take damage from multiple sources, such as an arrow and a dragon's breath, you make a separate saving throw for each source of damage.\n- **Being incapacitated or killed.** You lose concentration on a spell if you are incapacitated or if you die.\n\nThe GM might also decide that certain environmental phenomena, such as a wave crashing over you while you're on a storm-tossed ship, require you to succeed on a DC 10 Constitution saving throw to maintain concentration on a spell.",
				new[] { "concentration" }),
			it: ("Concentrazione", "Alcuni incantesimi richiedono di mantenere la concentrazione per restare attivi. Se il personaggio perde la concentrazione, l'incantesimo termina.\n\nSe un incantesimo va mantenuto con la concentrazione, lo indica la sua voce Durata, insieme a quanto a lungo ci si può concentrare su di esso. Il personaggio può interrompere la concentrazione in qualsiasi momento (non richiede alcuna azione).\n\nLe attività normali, come muoversi e attaccare, non interferiscono con la concentrazione. Questi fattori invece possono interromperla:\n- **Lanciare un altro incantesimo che richiede concentrazione.** Il personaggio perde la concentrazione su un incantesimo se ne lancia un altro che richiede concentrazione: non può concentrarsi su due incantesimi contemporaneamente.\n- **Subire danni.** Ogni volta che subisce danni mentre è concentrato su un incantesimo, deve effettuare un tiro salvezza su Costituzione per mantenere la concentrazione. La CD è pari a 10 o alla metà dei danni subiti, a seconda di quale valore sia più alto. Se subisce danni da più fonti, come una freccia e il soffio di un drago, effettua un tiro salvezza separato per ciascuna fonte.\n- **Essere incapacitato o ucciso.** Il personaggio perde la concentrazione su un incantesimo se diventa incapacitato o se muore.\n\nIl DM può anche stabilire che certi fenomeni ambientali, come un'onda che si abbatte sul personaggio mentre si trova su una nave in balia della tempesta, richiedano un tiro salvezza su Costituzione con CD 10 superato per mantenere la concentrazione su un incantesimo.",
				new[] { "concentrazione" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "spell-attack-rolls", RuleCategory.Rule,
			related: new[] { "attack-rolls" },
			en: ("Spell Attack Rolls", "Some spells require the caster to make an attack roll to determine whether the spell effect hits the intended target. Your attack bonus with a spell attack equals your spellcasting ability modifier + your proficiency bonus.\n\nMost spells that require attack rolls involve ranged attacks. Remember that you have disadvantage on a ranged attack roll if you are within 5 feet of a hostile creature that can see you and that isn't incapacitated.",
				new[] { "spell attack", "spell attacks" }),
			it: ("Tiri per colpire con gli incantesimi", "Alcuni incantesimi richiedono all'incantatore di effettuare un tiro per colpire per stabilire se l'effetto colpisce il bersaglio. Il bonus di attacco di un attacco con incantesimo è pari al modificatore di caratteristica da incantatore + il bonus di competenza.\n\nLa maggior parte degli incantesimi che richiedono un tiro per colpire prevede attacchi a distanza. Va ricordato che si subisce svantaggio a un tiro per colpire a distanza se ci si trova entro 1,5 metri da una creatura ostile che può vedere il personaggio e che non è incapacitata.",
				new[] { "attacco con incantesimo", "attacchi con incantesimo", "attacco con un incantesimo" }));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "combining-magical-effects", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Combining Magical Effects", "The effects of different spells add together while the durations of those spells overlap. The effects of the same spell cast multiple times don't combine, however. Instead, the most potent effect—such as the highest bonus-from those castings applies while their durations overlap.\n\nFor example, if two clerics cast _bless_ on the same target, that character gains the spell's benefit only once; he or she doesn't get to roll two bonus dice.",
				Array.Empty<string>()),
			it: ("Combinare effetti magici", "Gli effetti di incantesimi diversi si sommano finché le loro durate si sovrappongono. Gli effetti dello stesso incantesimo lanciato più volte, invece, non si combinano: finché le durate si sovrappongono, si applica soltanto l'effetto più potente tra quelli dei vari lanci, come il bonus più alto.\n\nPer esempio, se due chierici lanciano _Benedizione_ sullo stesso bersaglio, quel personaggio ottiene il beneficio dell'incantesimo una sola volta: non tira due dadi bonus.",
				Array.Empty<string>()));

		yield return RuleEntryFactory.Create(RulesetVersion.Dnd5e_2014, ContentSource.Srd51, "attunement", RuleCategory.Rule,
			related: Array.Empty<string>(),
			en: ("Attunement", "Some magic items require a creature to form a bond with them before their magical properties can be used. This bond is called attunement, and certain items have a prerequisite for it. If the prerequisite is a class, a creature must be a member of that class to attune to the item. (If the class is a spellcasting class, a monster qualifies if it has spell slots and uses that class's spell list.) If the prerequisite is to be a spellcaster, a creature qualifies if it can cast at least one spell using its traits or features, not using a magic item or the like.\n\nWithout becoming attuned to an item that requires attunement, a creature gains only its nonmagical benefits, unless its description states otherwise. For example, a magic shield that requires attunement provides the benefits of a normal shield to a creature not attuned to it, but none of its magical properties.\n\nAttuning to an item requires a creature to spend a short rest focused on only that item while being in physical contact with it (this can't be the same short rest used to learn the item's properties). This focus can take the form of weapon practice (for a weapon), meditation (for a wondrous item), or some other appropriate activity. If the short rest is interrupted, the attunement attempt fails. Otherwise, at the end of the short rest, the creature gains an intuitive understanding of how to activate any magical properties of the item, including any necessary command words.\n\nAn item can be attuned to only one creature at a time, and a creature can be attuned to no more than three magic items at a time. Any attempt to attune to a fourth item fails; the creature must end its attunement to an item first. Additionally, a creature can't attune to more than one copy of an item. For example, a creature can't attune to more than one _ring of protection_ at a time.\n\nA creature's attunement to an item ends if the creature no longer satisfies the prerequisites for attunement, if the item has been more than 100 feet away for at least 24 hours, if the creature dies, or if another creature attunes to the item. A creature can also voluntarily end attunement by spending another short rest focused on the item, unless the item is cursed.",
				new[] { "attunement" }),
			it: ("Sintonia", "Alcuni oggetti magici richiedono che una creatura stabilisca un legame con loro prima di poterne usare le proprietà magiche. Questo legame si chiama sintonia, e alcuni oggetti hanno un prerequisito per ottenerla. Se il prerequisito è una classe, la creatura deve appartenere a quella classe per entrare in sintonia con l'oggetto (se si tratta di una classe da incantatore, un mostro soddisfa il requisito se ha slot incantesimo e usa la lista degli incantesimi di quella classe). Se il prerequisito è essere un incantatore, la creatura lo soddisfa se può lanciare almeno un incantesimo grazie ai suoi tratti o privilegi, non tramite un oggetto magico o simili.\n\nSenza entrare in sintonia con un oggetto che la richiede, una creatura ne ottiene soltanto i benefici non magici, a meno che la descrizione dell'oggetto non dica altrimenti. Per esempio, uno scudo magico che richiede sintonia fornisce a una creatura non in sintonia i benefici di un normale scudo, ma nessuna delle sue proprietà magiche.\n\nPer entrare in sintonia con un oggetto, una creatura deve trascorrere un riposo breve concentrandosi soltanto su quell'oggetto e restando a contatto fisico con esso (non può essere lo stesso riposo breve usato per scoprirne le proprietà). La concentrazione può consistere nell'esercitarsi con l'arma (per un'arma), nel meditare (per un oggetto meraviglioso) o in un'altra attività adatta. Se il riposo breve viene interrotto, il tentativo fallisce; altrimenti, al termine del riposo, la creatura comprende in modo intuitivo come attivare le proprietà magiche dell'oggetto, comprese le eventuali parole di comando.\n\nUn oggetto può essere in sintonia con una sola creatura alla volta, e una creatura può essere in sintonia con un massimo di tre oggetti magici alla volta. Qualsiasi tentativo di entrare in sintonia con un quarto oggetto fallisce: la creatura deve prima porre fine alla sintonia con un altro oggetto. Inoltre, una creatura non può essere in sintonia con più di una copia dello stesso oggetto: per esempio, non può essere in sintonia con più di un _anello di protezione_ alla volta.\n\nLa sintonia di una creatura con un oggetto termina se la creatura non soddisfa più i prerequisiti, se l'oggetto si è trovato a più di 30 metri da lei per almeno 24 ore, se la creatura muore o se un'altra creatura entra in sintonia con l'oggetto. Una creatura può anche porre fine volontariamente alla sintonia trascorrendo un altro riposo breve concentrata sull'oggetto, a meno che l'oggetto non sia maledetto.",
				new[] { "sintonia" }));
	}
}
